const HF_REFERENCE_PRESETS={hf_deg_physiological_decrement_onset:{name:"Physiological system decrement that degrades tasks",value:10,unit:"% (Δ, ≥10%)",kind:"degradation",group:"Physical workload — general degradation",source:"NASA/SP-2010-3407 (HIDH) §5.2.1",page:102,applicability:"general",quote:"Decrements in these physiological systems at a magnitude of 10% or more can severely reduce task performance.",note:"Threshold at which cardiorespiratory/musculoskeletal decrements meaningfully impair task performance.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_vo2max_men_50th_20_29:{name:"VO2max, men 20-29, 50th percentile",value:43.9,unit:"mL/kg/min",kind:"capacity",group:"Aerobic capacity — VO2max",source:"NASA/SP-2010-3407 (HIDH) §5.2.2 (ACSM 2000)",page:103,applicability:"general",quote:"50th Percentile 43.9 42.4 40.4 36.7 33.1",note:"Median aerobic capacity, men age 20-29 (Table 5.2-1; declines with age).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_vo2max_men_20th_20_29:{name:"VO2max, men 20-29, 20th percentile (risk threshold)",value:38.1,unit:"mL/kg/min",kind:"capacity",group:"Aerobic capacity — VO2max",source:"NASA/SP-2010-3407 (HIDH) §5.2.2 (ACSM 2000)",page:103,applicability:"general",quote:"20th Percentile 38.1 36.7 34.6 31.1 27.4",note:"At/below 20th percentile individuals have difficulty with daily-living tasks and higher all-cause mortality risk.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_vo2max_women_50th_20_29:{name:"VO2max, women 20-29, 50th percentile",value:37.4,unit:"mL/kg/min",kind:"capacity",group:"Aerobic capacity — VO2max",source:"NASA/SP-2010-3407 (HIDH) §5.2.2 (ACSM 2000)",page:103,applicability:"general",quote:"50th Percentile 37.4 35.2 33.3 30.2 27.5",note:"Median aerobic capacity, women age 20-29 (Table 5.2-1).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_vo2max_women_20th_20_29:{name:"VO2max, women 20-29, 20th percentile (risk threshold)",value:31.6,unit:"mL/kg/min",kind:"capacity",group:"Aerobic capacity — VO2max",source:"NASA/SP-2010-3407 (HIDH) §5.2.2 (ACSM 2000)",page:103,applicability:"general",quote:"20th Percentile 31.6 29.9 28.0 25.5 23.7",note:"At/below 20th percentile: difficulty with daily-living tasks, elevated mortality risk (women 20-29).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_aerobic_capacity_postflight:{name:"Aerobic capacity reduction on return to 1g",value:15,unit:"% (Δ; 10–15%)",kind:"degradation",group:"Aerobic fitness — spaceflight adaptation",source:"NASA/SP-2010-3407 (HIDH) §5.2.2.1",page:104,applicability:"spaceflight",quote:"crewmembers experience an approximate 10% to 15% reduction in aerobic exercise capacity from pre-flight.",note:"Measured upon landing/return to 1g after ISS mission.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_aerobic_capacity_early_flight:{name:"Aerobic capacity drop in first weeks of microgravity",value:20,unit:"% (Δ, ~20%)",kind:"degradation",group:"Aerobic fitness — spaceflight adaptation",source:"NASA/SP-2010-3407 (HIDH) §5.2.2.1",page:104,applicability:"spaceflight",quote:"aerobic capacity is reduced dramatically (~20%) in the first few weeks of space flight",note:"Rapid in-flight VO2max reduction; recovers toward pre-flight over the mission.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_eva_duration:{name:"Shuttle EVA duration range",value:8,unit:"h (4–8 h)",kind:"capacity",group:"EVA workload — duration",source:"NASA/SP-2010-3407 (HIDH) §5.2.2.2",page:105,applicability:"spaceflight",quote:"EVA activity was generally low to moderate in intensity and ranged in duration from approximately 4-8 hours",note:"Typical Shuttle-era EVA duration; future exploration EVAs expected longer/higher intensity.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_eva_metabolic_apollo_lunar:{name:"EVA metabolic workload, Apollo (1/6 g)",value:234,unit:"kcal/h (0.80 L/min O2)",kind:"capacity",group:"EVA workload — metabolic rate",source:"NASA/SP-2010-3407 (HIDH) §5.2.2.2",page:105,applicability:"spaceflight",quote:"Apollo (1/6g) 234 kcal/h, 0.80 L/min",note:"Metabolic workload during lunar-surface EVA (Table 5.2-2).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_eva_metabolic_apollo_0g:{name:"EVA metabolic workload, Apollo (0 g)",value:151,unit:"kcal/h (0.51 L/min O2)",kind:"capacity",group:"EVA workload — metabolic rate",source:"NASA/SP-2010-3407 (HIDH) §5.2.2.2",page:105,applicability:"spaceflight",quote:"Apollo (0g) 151 kcal/h, 0.51 L/min",note:"Lowest tabulated EVA metabolic rate (microgravity Apollo EVA).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_eva_metabolic_skylab:{name:"EVA metabolic workload, Skylab",value:238,unit:"kcal/h (0.81 L/min O2)",kind:"capacity",group:"EVA workload — metabolic rate",source:"NASA/SP-2010-3407 (HIDH) §5.2.2.2",page:105,applicability:"spaceflight",quote:"Skylab 238 kcal/h, 0.81 L/min",note:"Highest tabulated EVA metabolic rate (Table 5.2-2).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_eva_metabolic_shuttle_early:{name:"EVA metabolic workload, Shuttle STS 1-54",value:205,unit:"kcal/h (0.76 L/min O2)",kind:"capacity",group:"EVA workload — metabolic rate",source:"NASA/SP-2010-3407 (HIDH) §5.2.2.2",page:105,applicability:"spaceflight",quote:"Shuttle (STS 1-54) 205 kcal/h, 0.76 L/min",note:"Metabolic workload during early Shuttle-era EVA (Table 5.2-2).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_eva_metabolic_shuttle_late:{name:"EVA metabolic workload, Shuttle STS 103-121",value:220,unit:"kcal/h (0.76 L/min O2)",kind:"capacity",group:"EVA workload — metabolic rate",source:"NASA/SP-2010-3407 (HIDH) §5.2.2.2",page:105,applicability:"spaceflight",quote:"Shuttle (STS 103-121) 220 kcal/h, 0.76 L/min",note:"Metabolic workload during later Shuttle-era EVA (Table 5.2-2).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_knee_extension_peak_torque:{name:"Knee extension peak torque, preflight baseline",value:176,unit:"N-m",kind:"capacity",group:"Muscle strength — lower limb",source:"NASA/SP-2010-3407 (HIDH) §5.2.3.1 (Lee et al. 2004)",page:107,applicability:"general",quote:"Knee Extension, Peak Torque (N-m) ... ISS 176±10 ... 136±10*",note:"ISS preflight 176±10 N-m; dropped postflight to 136±10, Table 5.2-3.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_knee_flexion_peak_torque:{name:"Knee flexion peak torque, preflight baseline",value:106,unit:"N-m",kind:"capacity",group:"Muscle strength — lower limb",source:"NASA/SP-2010-3407 (HIDH) §5.2.3.1 (Lee et al. 2004)",page:107,applicability:"general",quote:"Knee Flexion, Peak Torque (N-m) ... ISS 106±6 ... 74±7*",note:"ISS preflight 106±6 N-m; dropped postflight to 74±7, Table 5.2-3.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_muscle_strength_iss_6mo:{name:"Postural/locomotor strength decline after 6-month ISS",value:17,unit:"% (Δ; 8–17%)",kind:"degradation",group:"Muscle strength — spaceflight adaptation",source:"NASA/SP-2010-3407 (HIDH) §5.2.3.1",page:107,applicability:"spaceflight",quote:"Strength in these muscles groups declines 8% to 17% following a 6-month stay on the ISS.",note:"Trunk and lower-extremity locomotor/postural muscle strength loss.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_bmd_loss_rate:{name:"Bone mineral density loss rate in spaceflight",value:1.5,unit:"%/month (1.0–1.5)",kind:"degradation",group:"Bone — spaceflight adaptation",source:"NASA/SP-2010-3407 (HIDH) §5.2.4.1 (Shackelford 2004)",page:109,applicability:"spaceflight",quote:"decrements in bone mineral density during long-duration spaceflight at a rate of 1.0% to 1.5% per month",note:"~10x faster than osteoporotic loss in 1g; highest in the hip.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_visual_2d_orientation:{name:"2D static angular orientation perception precision",value:1,unit:"° (<1°)",kind:"error-rate",group:"Vision — static orientation precision",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Howard & Templeton 1966; Philips & Wilson 1984)",page:111,applicability:"general",quote:"estimating two-dimensional (2D) static angular orientation of objects with a precision better than 1º",note:"Depends on stimulus size and contrast.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_vestibular_tilt_precision:{name:"Otolith tilt (head vs gravity) precision",value:1,unit:"° (~1°)",kind:"error-rate",group:"Vestibular — tilt perception precision",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Howard & Templeton 1966)",page:111,applicability:"general",quote:"signal the angular position of the head with respect to gravity with a precision of about 1º",note:"Otolith-based tilt processing on Earth.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_motion_sickness_freq_peak:{name:"Motion-sickness susceptibility peak frequency (linear accel)",value:.1,unit:"Hz (0.1–0.3 Hz)",kind:"threshold",group:"Vestibular — motion sickness",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Wood 2002)",page:111,applicability:"general",quote:"A peak in motion sickness susceptibility occurs during linear accelerations around 0.1 to 0.3 Hz",note:"Frequency band where tilt/translation cannot be segregated by otoliths.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_wholebody_translation_vertical:{name:"Whole-body translation detection threshold, vertical",value:.15,unit:"m/s^2 (~0.15)",kind:"threshold",group:"Vestibular — motion detection",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Benson et al. 1986)",page:111,applicability:"general",quote:"Thresholds for perception of whole-body translation are significantly higher in the vertical direction (~0.15 m/s^2)",note:"Vertical linear-acceleration perception threshold; higher than horizontal.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_wholebody_translation_horizontal:{name:"Whole-body translation detection threshold, horizontal",value:.06,unit:"m/s^2 (~0.06)",kind:"threshold",group:"Vestibular — motion detection",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Benson et al. 1986)",page:111,applicability:"general",quote:"thresholds for movement in the horizontal directions (~0.06 m/s^2) (Benson et al., 1986).",note:"Horizontal linear-acceleration perception threshold.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_2d_speed_estimate:{name:"2D visual motion speed-estimate precision",value:5,unit:"% (as good as 5%)",kind:"error-rate",group:"Vision — motion estimation precision",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (McKee et al. 1986)",page:111,applicability:"general",quote:"with the precision of speed estimates being as good as 5% (McKee et al., 1986)",note:"Best-case 2D speed discrimination on a display.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_2d_direction_estimate:{name:"2D visual motion direction-estimate precision",value:1,unit:"° (<1°)",kind:"error-rate",group:"Vision — motion estimation precision",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Pantle & Sekuler 1969)",page:111,applicability:"general",quote:"and of direction estimates better than 1º (Pantle & Sekuler, 1969)",note:"Best-case 2D motion direction discrimination.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_lat_manual_control_lowcontrast_rt:{name:"Reaction-time increase per contrast halving below 16% contrast",value:35,unit:"ms (Δ, +35 ms)",kind:"latency",group:"Manual control — low-contrast displays",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Li et al. 2005)",page:112,applicability:"general",quote:"below 16% contrast, for every twofold reduction in luminance contrast, there is a 35-ms increase in reaction time",note:"Onset below 16% contrast; per twofold luminance-contrast reduction.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_manual_control_lowcontrast_rms:{name:"RMS error increase per contrast halving below 16% contrast",value:8,unit:"% (Δ, +8% RMS)",kind:"error-rate",group:"Manual control — low-contrast displays",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Li et al. 2005)",page:112,applicability:"general",quote:"and an 8% increase in root mean square error in a manual control task (Li et al., 2005)",note:"Manual-control tracking error increase per twofold contrast reduction below 16% contrast.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_3d_heading_estimate:{name:"3D self-translation (heading) estimate precision from optic flow",value:1,unit:"° (~1°)",kind:"error-rate",group:"Vision — heading estimation",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Warren et al. 1988)",page:112,applicability:"general",quote:"one's 3D direction of self-translation (heading) ... with an accuracy and precision approaching 1º (Warren et al., 1988)",note:"Pure translation; combined translation+rotation is 3-4x worse.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_time_to_contact_monocular:{name:"Monocular 3D closing-speed / time-to-contact precision",value:10,unit:"% (5–10%)",kind:"error-rate",group:"Vision — time-to-contact",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Regan & Hamstra 1993)",page:112,applicability:"general",quote:"time-to-contact is expected to be limited by the 5% to 10% precision of 2D speed estimation ... slightly better than 10%",note:"Monocular looming-based time-to-contact precision.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_stereomotion_closing_speed:{name:"Binocular stereomotion 3D closing-speed precision",value:25,unit:"% (≥25%)",kind:"error-rate",group:"Vision — stereomotion",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Brooks & Stone 2004)",page:112,applicability:"general",quote:"binocular stereomotion estimate of 3D closing speed ... less precise, typically 25% or higher (Brooks & Stone, 2004)",note:"Less precise than monocular; two eye views can be worse than one due to stereomotion suppression.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_lat_vor:{name:"Vestibulo-ocular reflex (VOR) latency",value:10,unit:"ms (~10 ms)",kind:"latency",group:"Gaze stabilization — VOR",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Ramachandran & Lisberger 2005)",page:112,applicability:"general",quote:"allow the oculomotor system to rapidly (latency: ~10 ms) stabilize the eyes",note:"Enables gaze stabilization during head motion.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_vor_frequency_range:{name:"VOR effective motion-frequency range",value:12,unit:"Hz (0.2 to ~12 Hz)",kind:"capacity",group:"Gaze stabilization — VOR",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Ramachandran & Lisberger 2005)",page:112,applicability:"general",quote:"over a wide range of motion frequencies from below 0.2 Hz up to about 12 Hz",note:"Upper frequency of effective VOR retinal-image stabilization.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_ocr_gain:{name:"Ocular counter-roll (OCR) reflex gain",value:10,unit:"% (10–30% gain)",kind:"capacity",group:"Gaze stabilization — OCR",source:"NASA/SP-2010-3407 (HIDH) §5.3.2 (Howard & Templeton 1966)",page:113,applicability:"general",quote:"The gain of the OCR is only about 10% to 30%, so it does not fully compensate for head roll",note:"Static head-roll torsional-eye compensation is only partial.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_okr_vor_crossover:{name:"OKR/VOR dominance crossover frequency",value:.5,unit:"Hz (~0.5 Hz)",kind:"threshold",group:"Gaze stabilization — OKR/VOR",source:"NASA/SP-2010-3407 (HIDH) §5.3.2",page:113,applicability:"general",quote:"OKR (which dominates ... below ~0.5 Hz) and the VOR (which dominates ... above ~0.5 Hz)",note:"OKR handles slow head motion, VOR faster; crossover ~0.5 Hz.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_motion_mulder:{name:"Mulder's constant — angular-velocity detection threshold (no vision)",value:2,unit:"°/s (~2°/s)",kind:"threshold",group:"Vestibular — motion detection",source:"NASA/SP-2010-3407 (HIDH) §5.3.3.1 (Gillingham & Wolfe 1985)",page:114,applicability:"aircraft",quote:"Mulder's constant ... is approximately 2º per second, and remains fairly constant for stimulus times of about 5 seconds or less",note:"Below this angular-velocity change, motions go undetected absent good visual cues (stimuli ≤~5 s).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_entry_g_hypersensitivity:{name:"Postflight vestibular hypersensitivity to entry g-loads",value:.5,unit:"g (perceived as 1–2 g)",kind:"degradation",group:"Vestibular — postflight hypersensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.3.3.1 (Parker et al. 1985)",page:114,applicability:"spaceflight",quote:"Entry loads of ~0.5g are often reported to feel more like 1g or 2g",note:"After adaptation to 0g; small head pitch/roll perceived as much larger.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_gain_disturbance_roll:{name:"Perceived surround roll per 20° head roll (entry/postflight)",value:70,unit:"° perceived (70–80° per 20°)",kind:"error-rate",group:"Vestibular — gain disturbance",source:"NASA/SP-2010-3407 (HIDH) §5.3.3.1 (Reschke et al. 1996)",page:115,applicability:"spaceflight",quote:"a 20° roll head movement resulted in perceived surround roll motion of 70° to 80°",note:"Overestimation (gain disturbance) reported during/after entry and landing.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_gain_disturbance_translation:{name:"Perceived self-translation per 20° head movement at wheels stop",value:.6,unit:"m (0.6–0.9 m per 20°)",kind:"error-rate",group:"Vestibular — gain disturbance",source:"NASA/SP-2010-3407 (HIDH) §5.3.3.1 (Reschke et al. 1996)",page:115,applicability:"spaceflight",quote:"the 20° head movement was perceived as 0.6 to 0.9 m of self-translation (Reschke et al., 1996)",note:"Head tilt misperceived as linear self-translation at Shuttle wheels stop.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_lat_temporal_disturbance:{name:"Perceived self-motion lag/persistence after head movement (entry)",value:.5,unit:"s (up to ~0.5 s)",kind:"latency",group:"Vestibular — temporal disturbance",source:"NASA/SP-2010-3407 (HIDH) §5.3.3.1 (Reschke et al. 1996)",page:115,applicability:"spaceflight",quote:"both increased over the first 3 days of flight from barely perceptible to 0.5 seconds",note:"Lag and persistence of perceived self-motion; most marked during 1.5g phase of entry.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_text_recognition_tilt:{name:"Face/printed-text recognition tilt limit",value:60,unit:"° (>~60°)",kind:"threshold",group:"Vision — orientation recognition",source:"NASA/SP-2010-3407 (HIDH) §5.3.3.3.1 (Corballis et al. 1978)",page:118,applicability:"general",quote:"Faces and printed text are difficult to recognize when tilted by more than about 60º (Corballis et al., 1978)",note:"Relevant to reading displays/labels at unfamiliar 0g orientations.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_shuttle_landing_precision:{name:"Postflight landing precision vs preflight trainer",value:50,unit:"% (Δ; half as precise)",kind:"degradation",group:"Manual control — postflight landing",source:"NASA/SP-2010-3407 (HIDH) §5.3.3.3.2 (Paloski et al. 2008)",page:118,applicability:"spaceflight",quote:"making actual Shuttle landings, on average, half as precise as preflight landings in trainers",note:"Attributed to otolith tilt-translation reinterpretation on return to 1g.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_obstacle_course_time_postflight:{name:"Functional-mobility obstacle-course time increase 1 day post-landing",value:48,unit:"% (Δ, +48%)",kind:"degradation",group:"Balance/locomotion — postflight",source:"NASA/SP-2010-3407 (HIDH) §5.3.3.3.2 (Mulavara et al. 2010)",page:119,applicability:"spaceflight",quote:"adaptation to spaceflight led to a 48% increase in time to complete the course 1 day after landing",note:"After 6-month flight; preflight scores recovered ~2 weeks after landing.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_focus_g_onset:{name:"Accommodation/focus difficulty onset under +Gx",value:3,unit:"+Gx (as low as +3Gx)",kind:"degradation",group:"Vision — hypergravity",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.1 (Chambers 1961)",page:120,applicability:"aircraft",quote:"Chambers (1961) reported difficulty focusing at levels as low as +3Gx",note:"Mechanical effect on eye optics; worse for -Gx (tearing).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_target_size_g:{name:"Target-size doubling required to be seen at +7Gx",value:7,unit:"+Gx (target 2x larger)",kind:"degradation",group:"Vision — hypergravity",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.1 (White & Jorve 1956)",page:120,applicability:"aircraft",quote:"a target needed to be twice as large to be seen at +7Gx",note:"Acuity degradation under sustained transverse g.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_contrast_sensitivity_g:{name:"Contrast increase needed for threshold discrimination at +5Gx",value:50,unit:"% (Δ, +50% at +5Gx)",kind:"degradation",group:"Vision — hypergravity",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.1 (Chambers & Hitchcock 1963)",page:120,applicability:"aircraft",quote:"a 50% increase in the contrast needed to make threshold discriminations at +5Gx",note:"Effect decreases at high display luminance; due to reduced retinal blood flow.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_peripheral_field_g_onset:{name:"Peripheral visual-field loss onset under +Gx",value:4,unit:"+Gx (decrement as low as +4Gx)",kind:"degradation",group:"Vision — hypergravity",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.1 (Chambers 1961)",page:120,applicability:"aircraft",quote:"some may experience at least some decrement in peripheral vision at g-loads as low as +4Gx",note:"Loss found at +6Gx, dramatic above +12Gx.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_lat_reaction_time_g:{name:"Reaction-time elevation under +6Gx",value:1,unit:"s (Δ, >1 s at +6Gx)",kind:"latency",group:"Reaction time — hypergravity",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.1 (Chambers & Hitchcock 1962/1963)",page:120,applicability:"aircraft",quote:"reaction times were elevated at +6Gx and some responses ... were elevated by more than a second",note:"Visual and auditory RT rise under hypergravity; audition more robust than vision.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_lat_target_acquisition_postflight:{name:"Target-acquisition delay postflight (head+eye)",value:1,unit:"s (>1 s)",kind:"latency",group:"Oculomotor — postflight target acquisition",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.2.2",page:121,applicability:"spaceflight",quote:"Acquisition of targets can be delayed by more than 1 second.",note:"When targets are outside effective oculomotor range on return to 1g.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_display_vibration_image_motion:{name:"Display-vibration image-motion below visual resolving limit",value:1,unit:"arcmin (<±1 arcmin)",kind:"threshold",group:"Vibration — display legibility",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.3 (Howard 1982)",page:121,applicability:"general",quote:"Vibration-induced lateral image motion smaller than ± 1 arcmin ... is below human visual resolving capability",note:"About ±0.5 point at a 24-inch viewing distance.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_vibration_blur:{name:"Retinal-image blur onset from higher-frequency oscillation",value:.2,unit:"° (>~0.2° at >~2-5 Hz)",kind:"threshold",group:"Vibration — display legibility",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.3 (O'Hanlon & Griffin 1971)",page:122,applicability:"general",quote:"Higher frequency oscillations (> ~2-5 Hz) above ~0.2° will cause blurring of the retinal image",note:"Degrades legibility at standard font sizes. Below ~1 Hz pursuit can track.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_observer_vibration_acuity:{name:"Acuity decrease under observer vibration at +0.5Gz RMS",value:5,unit:"Hz (5–20 Hz; ~3x acuity loss)",kind:"degradation",group:"Vibration — observer/VOR",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.3 (O'Briant & Ohlbaum 1970)",page:122,applicability:"aircraft",quote:"at +0.5Gz root mean square (RMS), there is about a threefold decrease in acuity for short viewing distances",note:"For short (~15.5 in.) viewing in 5-20 Hz; VOR compensation weakens above 5 Hz.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_vibration_vulnerable_range:{name:"Vibration vulnerable frequency range for visual function",value:2,unit:"Hz (2–30 Hz)",kind:"threshold",group:"Vibration — visual function",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.3",page:122,applicability:"spaceflight",quote:"The vulnerable range is therefore 2 to 30 Hz, which includes the expected solid rocket booster thrust oscillation ... near 12 Hz",note:"Eye mechanical resonance begins 20-70 Hz; includes ~12 Hz SRB thrust-oscillation peak.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_dl_display_accel_vibration_trigger:{name:"Sustained-accel / vibration level triggering robust-display rules",value:3,unit:"Gx (or 2Gz; vibration >0.15g)",kind:"design-limit",group:"Display design — g/vibration thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.4",page:122,applicability:"aircraft",quote:"sustained acceleration exceeds 3Gx or 2Gz (TBR), or vibration exceeds 0.15g zero-to-peak in any direction",note:"Condition triggering robust flight-display design guidelines (TBR values).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_dl_display_brightness:{name:"Minimum display brightness (robust design)",value:3,unit:"ft-lamberts (>3, TBR)",kind:"design-limit",group:"Display design — luminance",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.4",page:122,applicability:"aircraft",quote:"Visual displays should be centrally positioned, bright (> 3 ft-lamberts TBR)",note:"Design guideline for displays used during high-g/high-vibration phases (TBR).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_dl_display_contrast:{name:"Minimum display contrast (robust design)",value:30,unit:"% (>30%, TBR)",kind:"design-limit",group:"Display design — contrast",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.4",page:122,applicability:"aircraft",quote:"have high contrast (> 30% TBR)",note:"Design guideline for flight/monitoring displays (TBR).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_dl_display_viewing_distance:{name:"Minimum display viewing distance (accommodation)",value:49,unit:"cm (>49 cm, TBR)",kind:"design-limit",group:"Display design — accommodation",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.4",page:122,applicability:"aircraft",quote:"minimize demands on accommodation (viewing distance > 49 cm TBR)",note:"Reduces accommodation demand under altered-g/vibration (TBR).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_dl_display_symbol_subtense:{name:"Minimum symbology/text visual angle (robust design)",value:.4,unit:"° (≥0.4°, TBR)",kind:"design-limit",group:"Display design — symbol size",source:"NASA/SP-2010-3407 (HIDH) §5.3.4.4",page:122,applicability:"aircraft",quote:"any symbology or text should subtend at least 0.4° of visual angle, i.e., 10-pt font at 19 inches",note:"Maintains acuity margin under g/vibration (TBR).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_lat_reach_g:{name:"Reach movement slowing under +6Gx vs 1Gz",value:50,unit:"ms (Δ, ~50 ms slower)",kind:"latency",group:"Hand-eye — reaching under g",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.1 (Kaehler & Meehan 1960)",page:123,applicability:"aircraft",quote:"reaches are on average ~50 ms slower than at 1Gz (Kaehler & Meehan, 1960)",note:"Reaching possible at least up to +6Gx but slower.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_forward_reach_g:{name:"Forward reach displacement reduction under sustained g",value:6,unit:"% (Δ; 6%@3g,18%@4g,32%@5g)",kind:"degradation",group:"Hand-eye — reaching under g",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.1 (Schafer & Bagian 1993)",page:123,applicability:"aircraft",quote:"a 6% reduction in forward reach displacement at 3g (18% at 4g, 32% at 5g)",note:"40% of subjects declined exposure to loads over 4g.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_err_reach_direction_g:{name:"Closed-loop reach direction error above 2g (oblique reaches)",value:2,unit:"° (~2°, reaches >33° off-center)",kind:"error-rate",group:"Hand-eye — reaching under g",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.1 (Schafer & Bagian 1993)",page:123,applicability:"aircraft",quote:"predicts a closed-loop direction error of about 2° ... for oblique reaches directed more than 33° away from straight ahead",note:"Underestimates open-loop errors under time stress; onset above 2g.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_limit_manual_control_max_g:{name:"Peak +Gx allowing side-arm controller actuation",value:20,unit:"+Gx (>+20Gx; +15Gx control)",kind:"limit",group:"Manual control — extreme g tolerance",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.1 (Collins et al. 1958; Chambers 1961)",page:123,applicability:"aircraft",quote:"actuate a side-arm controller using hand-wrist-thumb movements at peak levels exceeding +20Gx",note:"Meaningful flight-control operations possible at +15Gx.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_vertigo_after_high_g:{name:"Post-exposure vertigo after +15Gx for 5 s",value:48,unit:"h (up to 48 h)",kind:"degradation",group:"Manual control — high-g aftereffects",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.1 (Duane et al. 1953)",page:123,applicability:"aircraft",quote:"vertigo for up to 48 hours has been reported after exposure to +15Gx for 5 seconds (Duane et al., 1953)",note:"Aftereffect of brief extreme transverse-g exposure.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_manual_control_decrement_g:{name:"Manual-control performance decrement at +6Gx",value:25,unit:"% (Δ, ~25% vs 1g)",kind:"degradation",group:"Manual control — hypergravity",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.1 (Chambers 1961; Chambers & Hitchcock 1963)",page:123,applicability:"aircraft",quote:"at +6Gx, they found a small but objective decrement in performance for all candidate controllers that averaged ~25% compared to 1g",note:"Magnitude depended strongly on controller design (threefold spread).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_control_error_g:{name:"Roll control-error increase at +6Gx (entry sim)",value:25,unit:"% (Δ, +25% at 6g)",kind:"degradation",group:"Manual control — hypergravity",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.1 (Wingrove et al. 1964)",page:124,applicability:"aircraft",quote:"about a ½-point increase in the Cooper-Harper rating and about a 25% increase in control error at 6g",note:"No effect at 3g; above 4g adverse; pilots generated ±0.5g oscillations at ~0.03 Hz.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_thr_vibration_manual_control_onset:{name:"Vibration RMS onset degrading manual control at +3.5Gx",value:.14,unit:"g RMS (>0.14)",kind:"threshold",group:"Vibration — manual control",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.3 (Vykukal & Dolkas 1966)",page:124,applicability:"aircraft",quote:"At +3.5Gx, vibration levels exceeding 0.14g RMS begin to adversely affect performance",note:"Onset of vibration-induced manual-control degradation under combined +3.5Gx.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_limit_vibration_coarse_only:{name:"Vibration RMS above which only coarse actions reliable",value:.3,unit:"g RMS (>0.3)",kind:"limit",group:"Vibration — manual control",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.3 (Vykukal & Dolkas 1966)",page:125,applicability:"aircraft",quote:"Above 0.3g RMS, only coarse actions (e.g., switch activation not under visual control) are reliable",note:"Fine/visually-guided control unreliable above this vibration level.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_limit_vibration_severe_degrade:{name:"Vibration RMS above which manual control severely degraded",value:.5,unit:"g RMS (>0.5)",kind:"limit",group:"Vibration — manual control",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.3 (Vykukal & Dolkas 1966)",page:125,applicability:"aircraft",quote:"above 0.5g RMS manual control is severely degraded, with potentially safety-compromising after-effects lasting minutes",note:"After-effects can persist minutes post-exposure.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_dl_reach_cone_g:{name:"Control-reach central cone above 2g",value:30,unit:"° cone (central; above 2g)",kind:"design-limit",group:"Controls — reach layout under g",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.4",page:125,applicability:"aircraft",quote:"reaches ... should be confined to a central 30° region for sustained acceleration levels above 2g",note:"Safe/effective reaches possible 2Gx-3Gx; target keys/switches within a central 30° cone.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_dl_vibration_binary_only:{name:"Vibration above which only binary non-visual tasks planned",value:.5,unit:"g zero-to-peak (>0.5, TBR)",kind:"design-limit",group:"Controls — vibration task limits",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.4",page:125,applicability:"aircraft",quote:"At vibration levels above 0.5g zero-to-peak (TBR), only simple non-visual binary motor tasks ... should be planned",note:"e.g., button pushes only, above this vibration level (TBR).",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_cap_periodic_g_protective:{name:"Periodic artificial-g protective against adaptation",value:.5,unit:"g (0.5 or 1.0 g)",kind:"capacity",group:"Countermeasure — artificial gravity",source:"NASA/SP-2010-3407 (HIDH) §5.3.5.4 (Moore et al. 2003)",page:125,applicability:"spaceflight",quote:"Periodic g loading of 0.5g or 1.0g seems to protect against oculomotor and perceptual adaptation",note:"May also protect hand-eye coordination from 0g adaptation.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_deg_muscle_mass_loss:{name:"Muscle-mass loss without countermeasures",value:50,unit:"% (20% short / 50% long mission)",kind:"degradation",group:"Muscle — spaceflight loss",source:"NASA/SP-2010-3407 (HIDH) §5.3.6.1 (Clement 2003)",page:126,applicability:"spaceflight",quote:"lose up to 20% of their muscle mass on short-duration missions, and as much as 50% on long-duration missions",note:"Primarily postural leg/back muscles if no countermeasures; affects postflight balance/locomotion.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_lat_balance_recovery_postflight:{name:"Postflight balance/functional-mobility recovery time",value:15,unit:"days (2–4 d short; 15 d long to 95%)",kind:"latency",group:"Balance/locomotion — postflight recovery",source:"NASA/SP-2010-3407 (HIDH) §5.3.6.1 (Mulavara et al. 2010)",page:126,applicability:"spaceflight",quote:"less than 20 days require from 2 to 4 days to recover ... 15 days to recover functional mobility to within 95% of preflight levels",note:"Recovery time scales with mission duration.",section:"§5.2 Physical Workload & §5.3 Sensorimotor Function"},hf_light_scatter_fraction:{name:"Fraction of light scattered beyond point spread",value:null,unit:"fraction (0.1 young – 0.5 old)",kind:"threshold",group:"Vision — optics",source:"NASA/SP-2010-3407 (HIDH) §5.4.5.4 (Westheimer & Liang 1995; Ginis et al. 2012)",page:131,applicability:"general",quote:"Estimates of the fraction of light scattered beyond the conventional point spread range from 0.1 in young eyes to 0.5 in older eyes",note:"Intraocular scatter fraction; responsible for glare.",section:"§5.4 Visual Perception"},hf_pupil_diameter_range:{name:"Normal pupil diameter range",value:null,unit:"mm (2–8)",kind:"design-limit",group:"Vision — optics",source:"NASA/SP-2010-3407 (HIDH) §5.4.5.3 (Winn et al. 1994)",page:130,applicability:"general",quote:"Normal pupil diameters range from 2 to 8 millimeters, and are generally smaller in older individuals",note:"Pupil diameter spans 2–8 mm depending on light level and age.",section:"§5.4 Visual Perception"},hf_lens_accommodation_range:{name:"Lens accommodation range",value:20,unit:"diopters (~20 ± 8)",kind:"capacity",group:"Vision — optics",source:"NASA/SP-2010-3407 (HIDH) §5.4.2",page:130,applicability:"general",quote:"the lens performs a fine-tuning through a range of about 20 ± 8 diopters",note:"Accommodation range declines with age; essentially absent beyond 50.",section:"§5.4 Visual Perception"},hf_visible_wavelength_range:{name:"Visible spectrum sensitivity range",value:null,unit:"nm (380–780)",kind:"design-limit",group:"Vision — spectral sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.6",page:131,applicability:"general",quote:"Sensitivity of the eye to light is confined to a range of wavelengths from about 380 to 780 nanometers.",note:"Eye responds to wavelengths ~380–780 nm.",section:"§5.4 Visual Perception"},hf_scotopic_peak_wavelength:{name:"Scotopic (rod) luminous efficiency peak",value:507,unit:"nm",kind:"design-limit",group:"Vision — spectral sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.6 (Fig 5.4-3)",page:132,applicability:"general",quote:"Scotopic peak = 507",note:"Rod/dim-illumination luminosity function peaks at 507 nm.",section:"§5.4 Visual Perception"},hf_photopic_peak_wavelength:{name:"Photopic (cone) luminous efficiency peak",value:555,unit:"nm",kind:"design-limit",group:"Vision — spectral sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.6 (Fig 5.4-3)",page:132,applicability:"general",quote:"Photopic peak = 555",note:"Cone/bright-illumination luminosity function peaks at 555 nm.",section:"§5.4 Visual Perception"},hf_visual_operating_range:{name:"Total light-intensity operating range of vision",value:13,unit:"log units",kind:"capacity",group:"Vision — light adaptation",source:"NASA/SP-2010-3407 (HIDH) §5.4.7 (Hood & Finkelstein 1986)",page:133,applicability:"general",quote:"The human visual system operates over a range of about 13 log units of light intensity.",note:"Full dynamic range across which vision can adapt.",section:"§5.4 Visual Perception"},hf_instantaneous_sensitivity_range:{name:"Momentary (instantaneous) sensitivity window",value:2,unit:"log units",kind:"capacity",group:"Vision — light adaptation",source:"NASA/SP-2010-3407 (HIDH) §5.4.7 (Hood & Finkelstein 1986)",page:133,applicability:"general",quote:"at any one time, it is sensitive to a much smaller range of about 2 log units",note:"Sliding sensitivity window at any single adaptation state.",section:"§5.4 Visual Perception"},hf_dark_adaptation_time:{name:"Complete dark adaptation time",value:10,unit:"minutes",kind:"latency",group:"Vision — light adaptation",source:"NASA/SP-2010-3407 (HIDH) §5.4.7 (Hood & Finkelstein 1986)",page:133,applicability:"general",quote:"complete dark adaptation from a bright adapting level may take as much as 10 minutes.",note:"Full dark adaptation from bright baseline; light adaptation completes in seconds.",section:"§5.4 Visual Perception"},hf_visual_threshold_luminance:{name:"Absolute visual threshold luminance",value:-5.15,unit:"log cd·m⁻²",kind:"threshold",group:"Vision — light adaptation",source:"NASA/SP-2010-3407 (HIDH) §5.4.7 (Fig 5.4-5)",page:135,applicability:"general",quote:"-5.15 ... Visual threshold",note:"Lowest luminance at which vision operates (Figure 5.4-5).",section:"§5.4 Visual Perception"},hf_color_vision_luminance_limit:{name:"Lower luminance limit for color vision",value:-1.19,unit:"log cd·m⁻²",kind:"threshold",group:"Vision — color",source:"NASA/SP-2010-3407 (HIDH) §5.4.7 (Fig 5.4-5)",page:135,applicability:"general",quote:"-1.19 ... Color vision limit",note:"Luminance below which color vision fails (Figure 5.4-5).",section:"§5.4 Visual Perception"},hf_rod_critical_summation_diameter:{name:"Ricco's-law critical diameter (dark-adapted rod)",value:1,unit:"degree",kind:"design-limit",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.1 (Hood & Finkelstein 1986)",page:136,applicability:"general",quote:"using rod vision, the critical diameter is about 1°",note:"Complete spatial summation up to ~1° for brief peripheral rod flashes.",section:"§5.4 Visual Perception"},hf_rod_threshold_luminance:{name:"Rod threshold at critical size",value:-5,unit:"log cd·m⁻²",kind:"threshold",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.1 (Hood & Finkelstein 1986)",page:136,applicability:"general",quote:"the threshold at that size is about −5 log cd·m⁻²",note:"Threshold luminance at the ~1° critical diameter, dark-adapted.",section:"§5.4 Visual Perception"},hf_critical_diameter_short_bright:{name:"Critical diameter, short duration bright background",value:.4,unit:"degree",kind:"design-limit",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.1 (Barlow 1958)",page:136,applicability:"general",quote:"For short duration (8.5 ms) on a bright background, it is about 0.4°",note:"Critical summation diameter shrinks on bright backgrounds / short exposures.",section:"§5.4 Visual Perception"},hf_critical_diameter_long_bright:{name:"Critical diameter, long duration bright background",value:.2,unit:"degree",kind:"design-limit",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.1 (Barlow 1958)",page:136,applicability:"general",quote:"for long durations (930 ms) on a bright background, it is about 0.2°",note:"Critical summation diameter for long exposure on bright background.",section:"§5.4 Visual Perception"},hf_min_contrast_threshold_2deg_photopic:{name:"Lowest contrast threshold (2° target, photopic)",value:.0077,unit:"contrast (fraction)",kind:"threshold",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.1 (Blackwell 1946)",page:136,applicability:"general",quote:"the lowest threshold is 0.0077, or just under 1% contrast, for a target of 2° diameter.",note:"Measured minimum contrast threshold on photopic background for a 2° disk.",section:"§5.4 Visual Perception"},hf_acuity_standard_stroke_width:{name:"Standard optotype stroke width",value:1,unit:"arcmin",kind:"design-limit",group:"Vision — acuity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.2 (NAS-NRC 1980)",page:137,applicability:"general",quote:"the individual strokes are all 1 arcmin wide, and the total height and width are 5 arcmin",note:"Standard Sloan-letter stroke width (minimum angle of resolution reference).",section:"§5.4 Visual Perception"},hf_acuity_letter_standard_size:{name:"Standard optotype total size",value:5,unit:"arcmin",kind:"design-limit",group:"Vision — acuity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.2 (NAS-NRC 1980)",page:137,applicability:"general",quote:"the total height and width are 5 arcmin (NAS-NRC, 1980)",note:"Standard letter subtends 5 arcmin; acuity is smallest identifiable relative to this.",section:"§5.4 Visual Perception"},hf_landolt_gap_standard:{name:"Landolt ring standard gap",value:1,unit:"arcmin",kind:"design-limit",group:"Vision — acuity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.2",page:137,applicability:"general",quote:"consists of a ring with a gap of 1 arcmin at the standard size.",note:"Landolt-C gap size defining standard (20/20) acuity target.",section:"§5.4 Visual Perception"},hf_acuity_2020_logmar:{name:"20/20 acuity in logMAR",value:0,unit:"logMAR",kind:"design-limit",group:"Vision — acuity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.2",page:137,applicability:"general",quote:"So-called 20/20 acuity corresponds to logMAR = 0.",note:"Reference-normal acuity anchor.",section:"§5.4 Visual Perception"},hf_acuity_young_adult_logmar:{name:"Mean logMAR acuity, young adults",value:-.1,unit:"logMAR",kind:"capacity",group:"Vision — acuity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.2 (Ohlsson & Villarreal 2005)",page:137,applicability:"general",quote:"Actual mean logMAR acuity for young adults is about −0.1",note:"Typical young-adult acuity slightly better than 20/20.",section:"§5.4 Visual Perception"},hf_peak_contrast_sensitivity:{name:"Peak spatial contrast sensitivity",value:500,unit:"sensitivity (1/contrast)",kind:"capacity",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.3 (van Nes & Bouman 1967)",page:138,applicability:"general",quote:"a contrast sensitivity peak of about 2.7 log units (about 500) at around 4 to 8 cycles/degree.",note:"Peak SCSF sensitivity (~2.7 log units) at 4–8 cy/deg on bright background.",section:"§5.4 Visual Perception"},hf_min_contrast_threshold_optimal:{name:"Minimum contrast threshold, optimal conditions",value:.002,unit:"contrast (fraction)",kind:"threshold",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.3",page:138,applicability:"general",quote:"Under optimal conditions of measurement (high luminance, large grating, static presentation, long duration, young observer), this is about 0.002.",note:"Smallest detectable contrast at peak of the SCSF.",section:"§5.4 Visual Perception"},hf_peak_spatial_frequency:{name:"Most visible (peak) spatial frequency",value:4,unit:"cycles/degree",kind:"design-limit",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.3",page:138,applicability:"general",quote:"The frequency at which the peak occurs (around 4 cycles/degree or a stripe width of 0.125°)",note:"Spatial frequency of maximum sensitivity (stripe width ~0.125°).",section:"§5.4 Visual Perception"},hf_spatial_frequency_upper_limit:{name:"Upper spatial-frequency limit of vision",value:60,unit:"cycles/degree",kind:"design-limit",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.3",page:138,applicability:"general",quote:"The high frequency limit, at around 60 cycles/degree (a stripe width of 0.5 arcmin)",note:"Smallest detectable image element ~0.5 arcmin stripe width.",section:"§5.4 Visual Perception"},hf_csf_eccentricity_decline:{name:"Contrast-sensitivity decline with eccentricity",value:.025,unit:"log units/cycle",kind:"degradation",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.3 (Robson & Graham 1981)",page:140,applicability:"general",quote:"The gray line shows a decline of 1/40 log units per cycle.",note:"Sensitivity falls ~1/40 log unit per cycle of eccentricity from fixation.",section:"§5.4 Visual Perception"},hf_cs_age_decline_16cpd:{name:"Contrast sensitivity age decline at 16 cy/deg",value:.1,unit:"log units/decade",kind:"degradation",group:"Vision — aging",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.6 (Owsley et al. 1983)",page:141,applicability:"general",quote:"contrast sensitivity at 16 cycles/degree declines by about 0.1 log unit per decade",note:"Adult aging 20s–80s, no ocular pathology.",section:"§5.4 Visual Perception"},hf_acuity_age_decline_logmar:{name:"logMAR acuity age decline (20s–80s)",value:.07,unit:"log units/decade",kind:"degradation",group:"Vision — aging",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.6 (Owsley et al. 1983)",page:141,applicability:"general",quote:"logMAR acuity declines by about 0.07 log unit per decade (Owsley et al., 1983).",note:"Acuity degradation rate across adulthood.",section:"§5.4 Visual Perception"},hf_acuity_age_decline_65_85:{name:"Acuity age decline, ages 65–85",value:.09,unit:"log units/decade",kind:"degradation",group:"Vision — aging",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.6 (Rubin et al. 1997)",page:141,applicability:"general",quote:"From ages 65 to 85, acuity declines about 0.09 log units per decade",note:"Faster acuity loss in older cohort.",section:"§5.4 Visual Perception"},hf_peak_cs_age_decline_65_85:{name:"Peak contrast sensitivity age decline, 65–85",value:.11,unit:"log units/decade",kind:"degradation",group:"Vision — aging",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.6 (Rubin et al. 1997)",page:141,applicability:"general",quote:"peak contrast sensitivity declines about 0.11 log unit per decade (Rubin et al., 1997).",note:"Peak-sensitivity loss rate in older cohort.",section:"§5.4 Visual Perception"},hf_lifetime_vision_decline_80s:{name:"Cumulative acuity/sensitivity decline by 80s",value:null,unit:"% (55–70%)",kind:"degradation",group:"Vision — aging",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.6",page:141,applicability:"general",quote:"by the 80s both acuity and peak sensitivity may have declined by as much as 55% to 70%.",note:"Cumulative decline from 20s peak.",section:"§5.4 Visual Perception"},hf_contrast_threshold_photopic_moderate:{name:"Typical contrast threshold, moderate photopic",value:.01,unit:"contrast (fraction)",kind:"threshold",group:"Vision — spatial sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.8.7",page:141,applicability:"general",quote:"For moderate-size targets on moderate photopic backgrounds, contrast threshold is around 0.01.",note:"Rule-of-thumb operational contrast threshold.",section:"§5.4 Visual Perception"},hf_bloch_critical_duration_bright:{name:"Bloch's-law critical duration, bright photopic",value:30,unit:"ms",kind:"design-limit",group:"Vision — temporal sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.9.2 (Roufs 1972)",page:142,applicability:"general",quote:"contrast thresholds decline approximately in proportion to duration, up to a duration of about 30 ms",note:"Complete temporal summation up to ~30 ms on bright background.",section:"§5.4 Visual Perception"},hf_bloch_critical_duration_dim:{name:"Bloch's-law critical duration, dim photopic",value:100,unit:"ms",kind:"design-limit",group:"Vision — temporal sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.9.2",page:142,applicability:"general",quote:"the critical duration is longer, approaching 100 ms for the dimmest photopic backgrounds.",note:"Temporal summation window lengthens toward 100 ms as background dims.",section:"§5.4 Visual Perception"},hf_cff_range:{name:"Critical fusion frequency range vs light level",value:null,unit:"Hz (<20 to >60)",kind:"design-limit",group:"Vision — temporal sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.9.4",page:144,applicability:"general",quote:"they increase in frequency with light level, ranging from below 20 Hz to above 60 Hz.",note:"CFF rises from <20 Hz (dim) to >60 Hz (bright).",section:"§5.4 Visual Perception"},hf_tcsf_peak_photopic:{name:"Temporal CSF peak frequency, photopic",value:null,unit:"Hz (4–8)",kind:"design-limit",group:"Vision — temporal sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.9.8",page:146,applicability:"general",quote:"At photopic light levels, the TCSF peak is around 4 to 8 Hz, and the CFF is around 60 to 70 Hz.",note:"Peak temporal contrast sensitivity at 4–8 Hz under photopic conditions.",section:"§5.4 Visual Perception"},hf_cff_photopic:{name:"Critical fusion frequency, photopic",value:null,unit:"Hz (60–70)",kind:"design-limit",group:"Vision — temporal sensitivity",source:"NASA/SP-2010-3407 (HIDH) §5.4.9.8",page:146,applicability:"general",quote:"At photopic light levels, the TCSF peak is around 4 to 8 Hz, and the CFF is around 60 to 70 Hz.",note:"Flicker fusion ~60–70 Hz at photopic light levels.",section:"§5.4 Visual Perception"},hf_photopic_region_threshold:{name:"Photopic-region lower luminance bound",value:10,unit:"cd·m⁻²",kind:"design-limit",group:"Vision — color",source:"NASA/SP-2010-3407 (HIDH) §5.4.10.1",page:147,applicability:"general",quote:"In the photopic region of intensity (approximately > 10 cd·m⁻²)",note:"Approximate luminance floor for full photopic/color vision.",section:"§5.4 Visual Perception"},hf_chromatic_csf_shift:{name:"Chromatic spatial-CSF frequency shift",value:4,unit:"× (factor)",kind:"degradation",group:"Vision — color",source:"NASA/SP-2010-3407 (HIDH) §5.4.10.5 (Mullen 1985)",page:150,applicability:"general",quote:"chromatic spatial contrast sensitivity is shifted toward lower frequencies by about a factor of four",note:"Chromatic pathways ~4× lower spatial resolution than luminance.",section:"§5.4 Visual Perception"},hf_color_deficiency_incidence_men:{name:"Anomalous color-vision incidence, men",value:8,unit:"% (up to)",kind:"error-rate",group:"Vision — color deficiency",source:"NASA/SP-2010-3407 (HIDH) §5.4.10.6 (Gegenfurtner & Sharpe 1999)",page:150,applicability:"general",quote:"In men, total incidence may be as high as 8%, with deuteranomaly the most common at about 4.6%",note:"Upper-bound total prevalence of color-vision deficiency in males.",section:"§5.4 Visual Perception"},hf_deuteranomaly_incidence_men:{name:"Deuteranomaly incidence, men",value:4.6,unit:"%",kind:"error-rate",group:"Vision — color deficiency",source:"NASA/SP-2010-3407 (HIDH) §5.4.10.6 (Gegenfurtner & Sharpe 1999)",page:150,applicability:"general",quote:"In men, total incidence may be as high as 8%, with deuteranomaly the most common at about 4.6%",note:"Most common color deficiency (M-cone anomaly) in males.",section:"§5.4 Visual Perception"},hf_other_lm_cone_incidence:{name:"Other L/M cone anomaly incidence",value:1,unit:"% (each)",kind:"error-rate",group:"Vision — color deficiency",source:"NASA/SP-2010-3407 (HIDH) §5.4.10.6",page:150,applicability:"general",quote:"with the other L and M cone cases at about 1% each.",note:"Protan/other L- and M-cone defects ~1% each in males.",section:"§5.4 Visual Perception"},hf_s_cone_defect_incidence:{name:"S-cone (tritan) defect incidence",value:.002,unit:"%",kind:"error-rate",group:"Vision — color deficiency",source:"NASA/SP-2010-3407 (HIDH) §5.4.10.6",page:150,applicability:"general",quote:"S cone defects are much rarer (around 0.002%), and probably equally common in both sexes.",note:"Rare tritan defects, sex-independent.",section:"§5.4 Visual Perception"},hf_color_deficiency_incidence_women:{name:"Anomalous color-vision incidence, women",value:.5,unit:"% (<0.5%)",kind:"error-rate",group:"Vision — color deficiency",source:"NASA/SP-2010-3407 (HIDH) §5.4.10.6 (Gegenfurtner & Sharpe 1999)",page:150,applicability:"general",quote:"having an incidence of less than 0.5 %",note:"Prevalence in females (much rarer than males).",section:"§5.4 Visual Perception"},hf_color_search_effective_limit:{name:"Effective color-coding count limit",value:9,unit:"colors",kind:"design-limit",group:"Vision — color coding",source:"NASA/SP-2010-3407 (HIDH) §5.4.10.7 (Boynton 1989)",page:150,applicability:"general",quote:"becomes less effective as the number of colors exceeds nine",note:"Color coding for search/segregation degrades beyond nine colors.",section:"§5.4 Visual Perception"},hf_basic_color_terms:{name:"Number of basic color terms",value:11,unit:"colors",kind:"design-limit",group:"Vision — color coding",source:"NASA/SP-2010-3407 (HIDH) §5.4.10.7 (Boynton 1989)",page:150,applicability:"general",quote:"there are eleven basic color terms, which are more reliable than others",note:"Eleven basic colors are faster/more reliable to name and discriminate.",section:"§5.4 Visual Perception"},hf_shuttle_acuity_decrease:{name:"Acuity decrease during Space Shuttle missions",value:.04,unit:"logMAR",kind:"degradation",group:"Vision — spaceflight",source:"NASA/SP-2010-3407 (HIDH) §5.4.12.1 (O'Neal et al. 1992)",page:151,applicability:"spaceflight",quote:"a significant but very small (0.04 logMAR) decrease in acuity",note:"On brief (≤8-day) Shuttle missions relative to ground.",section:"§5.4 Visual Perception"},hf_iss_hyperopic_shift:{name:"Hyperopic refractive shift, 6-month ISS",value:.84,unit:"diopters",kind:"degradation",group:"Vision — spaceflight",source:"NASA/SP-2010-3407 (HIDH) §5.4.12.1 (Mader et al. 2011)",page:152,applicability:"spaceflight",quote:"largely hyperopic shifts averaging 0.84 diopters (D) observed in seven astronauts following ISS missions of 6 months.",note:"Mean refractive change in 7 astronauts after long-duration flight.",section:"§5.4 Visual Perception"},hf_acuity_degradation_report_short:{name:"Self-reported acuity degradation, short-duration crews",value:29,unit:"%",kind:"error-rate",group:"Vision — spaceflight",source:"NASA/SP-2010-3407 (HIDH) §5.4.12.1",page:152,applicability:"spaceflight",quote:"short-duration and long-duration mission crews indicate that 29% and 60%, respectively, report degradation in visual acuity.",note:"Postflight questionnaire, short-duration crews.",section:"§5.4 Visual Perception"},hf_acuity_degradation_report_long:{name:"Self-reported acuity degradation, long-duration crews",value:60,unit:"%",kind:"error-rate",group:"Vision — spaceflight",source:"NASA/SP-2010-3407 (HIDH) §5.4.12.1",page:152,applicability:"spaceflight",quote:"short-duration and long-duration mission crews indicate that 29% and 60%, respectively, report degradation in visual acuity.",note:"Postflight questionnaire, long-duration crews.",section:"§5.4 Visual Perception"},hf_cosmic_ray_light_flash_rate:{name:"Cosmic-ray-induced light flash rate",value:null,unit:"per minute (0.1–0.5)",kind:"capacity",group:"Vision — spaceflight",source:"NASA/SP-2010-3407 (HIDH) §5.4.12.1 (Avdeev et al. 2002; Casolino et al. 2003)",page:152,applicability:"spaceflight",quote:"These flashes occur at rates from 0.1 to 0.5 per minute, depending on shielding and other obstructions",note:"Phosphene flash rate from energetic particles.",section:"§5.4 Visual Perception"},hf_space_light_level_increase:{name:"Space vs Earth sunlight level increase",value:25,unit:"% (~greater)",kind:"design-limit",group:"Vision — spaceflight",source:"NASA/SP-2010-3407 (HIDH) §5.4.12.2 (Parker & West 1973)",page:152,applicability:"spaceflight",quote:"somewhat increases light levels relative to sunlight on Earth (perhaps 25% greater)",note:"Unfiltered sunlight in space ~25% brighter than at Earth's surface.",section:"§5.4 Visual Perception"},hf_gz_peripheral_vision_loss:{name:"+Gz threshold for peripheral vision loss",value:3.5,unit:"G",kind:"threshold",group:"Vision — acceleration",source:"NASA/SP-2010-3407 (HIDH) §5.4.12.2 (Tredici & Ivan 2008)",page:153,applicability:"aircraft",quote:"Accelerations of greater than +3.5Gz may cause loss of peripheral vision",note:"Grey-out / peripheral vision loss onset under +Gz.",section:"§5.4 Visual Perception"},hf_gz_blackout_vision:{name:"+Gz threshold for complete vision loss (blackout)",value:4,unit:"G",kind:"threshold",group:"Vision — acceleration",source:"NASA/SP-2010-3407 (HIDH) §5.4.12.2 (Tredici & Ivan 2008)",page:153,applicability:"aircraft",quote:"accelerations greater than +4Gz may cause complete loss of vision (blackout).",note:"Full visual blackout onset under +Gz.",section:"§5.4 Visual Perception"},hf_g_loc_threshold:{name:"Acceleration threshold for loss of consciousness",value:null,unit:"G (4.5–6)",kind:"threshold",group:"Vision — acceleration",source:"NASA/SP-2010-3407 (HIDH) §5.4.12.2 (Tredici & Ivan 2008)",page:153,applicability:"aircraft",quote:"At 4.5 to 6G, consciousness may be lost.",note:"G-LOC range 4.5–6 G.",section:"§5.4 Visual Perception"},hf_vibration_blur_frequency:{name:"Vibration frequency degrading acuity",value:15,unit:"Hz (>15)",kind:"design-limit",group:"Vision — vibration",source:"NASA/SP-2010-3407 (HIDH) §5.4.12.2 (Tredici & Ivan 2008)",page:153,applicability:"aircraft",quote:"frequencies above 15 Hz that approach or exceed flicker fusion are likely to be the most problematic.",note:"Vibration blurs target; >15 Hz near flicker fusion most degrading to acuity.",section:"§5.4 Visual Perception"},hf_hearing_frequency_range_young:{name:"Audible frequency range (healthy young person)",value:null,unit:"Hz (20–20,000)",kind:"threshold",group:"Audition — nature of sound",source:"NASA/SP-2010-3407 (HIDH) §5.5.2.1",page:155,applicability:"general",quote:"approximately 20 to 20,000 cycles per second for a healthy young person",note:"Nominal human hearing bandwidth.",section:"§5.5 Auditory Perception"},hf_quietest_audible_pressure:{name:"Quietest audible sound pressure",value:20,unit:"µPa",kind:"threshold",group:"Audition — nature of sound",source:"NASA/SP-2010-3407 (HIDH) §5.5.2.1",page:156,applicability:"general",quote:"The quietest sound a healthy young person can hear is equivalent to 20 micropascals (0.00002 Pa)",note:"Reference sound pressure (0 dB SPL) equals 20 µPa.",section:"§5.5 Auditory Perception"},hf_loudest_pain_free_pressure:{name:"Loudest pain-free sound pressure",value:200,unit:"Pa",kind:"limit",group:"Audition — nature of sound",source:"NASA/SP-2010-3407 (HIDH) §5.5.2.1",page:156,applicability:"general",quote:"the loudest sound a person can hear without pain is about 200 Pa",note:"Upper pressure limit before pain.",section:"§5.5 Auditory Perception"},hf_threshold_of_pain_spl:{name:"Threshold of pain (SPL)",value:140,unit:"dB SPL",kind:"limit",group:"Audition — nature of sound",source:"NASA/SP-2010-3407 (HIDH) §5.5.2.1 Table 5.5-1",page:156,applicability:"general",quote:"200 [Pa] ... 140 ... Threshold of pain",note:"Table 5.5-1 maps 200 Pa to 140 dB SPL.",section:"§5.5 Auditory Perception"},hf_speech_intelligibility_pressure_floor:{name:"Cabin pressure below which speech understanding degrades",value:69,unit:"kPa (10 psia)",kind:"degradation",group:"Audition — nature of sound",source:"NASA/SP-2010-3407 (HIDH) §5.5.2.1 (Lange et al. 2005)",page:157,applicability:"spaceflight",quote:"pressures below about 69.0 kPa (10 psia) result in degradation of a crewmember's ability to understand speech",note:"Low ambient pressure degrades speech transmission.",section:"§5.5 Auditory Perception"},hf_discomfort_pain_onset_spl:{name:"Discomfort/pain onset level",value:null,unit:"dB SPL (110–120)",kind:"limit",group:"Audition — thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.1",page:158,applicability:"general",quote:"at about 110-120 dB SPL, sounds will begin to cause discomfort or pain",note:"Upper end of auditory sensitivity range.",section:"§5.5 Auditory Perception"},hf_permanent_damage_spl:{name:"Level above which short exposure may cause permanent damage",value:115,unit:"dB SPL",kind:"limit",group:"Audition — thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.1",page:158,applicability:"general",quote:"short-term exposure to levels above 115 dB SPL may cause permanent damage to the ear",note:"Damage-risk ceiling for brief exposures.",section:"§5.5 Auditory Perception"},hf_intensity_change_detection_ceiling:{name:"Level where intensity-change detection deteriorates",value:100,unit:"dB SPL",kind:"limit",group:"Audition — thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.1",page:158,applicability:"general",quote:"the ability to detect a change in intensity begins to deteriorate at about 100 dB SPL",note:"Upper working-region bound for intensity discrimination.",section:"§5.5 Auditory Perception"},hf_best_sensitivity_frequency_range:{name:"Frequency region of greatest hearing sensitivity",value:null,unit:"kHz (1–6)",kind:"threshold",group:"Audition — thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.1 (Moore 2004)",page:159,applicability:"general",quote:"Both the MAP and MAF show greatest sensitivity in the region of 1 to 6 kHz",note:"Best absolute-threshold sensitivity 1–6 kHz.",section:"§5.5 Auditory Perception"},hf_binaural_maf_advantage:{name:"Binaural MAF threshold advantage over monaural MAP",value:null,unit:"dB (6–10 lower)",kind:"threshold",group:"Audition — thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.1 (Moore 2004)",page:159,applicability:"general",quote:"binaural MAF thresholds are consistently about 6 to 10 dB lower than the monaural MAP",note:"Binaural listening lowers threshold by 6–10 dB.",section:"§5.5 Auditory Perception"},hf_normal_threshold_variability:{name:"Individual variability still considered normal",value:20,unit:"dB (±)",kind:"threshold",group:"Audition — thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.1",page:159,applicability:"general",quote:'a 20-dB difference from the mean threshold at a particular frequency may still be considered "normal."',note:"Absolute thresholds vary up to ±20 dB within normal range.",section:"§5.5 Auditory Perception"},hf_temporal_integration_time_constant:{name:"Auditory temporal-integration time constant",value:null,unit:"ms (200–500)",kind:"latency",group:"Audition — thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.1 (Moore 2004)",page:159,applicability:"general",quote:"a time constant for temporal integration on the order of 200 to 500 ms",note:"Below ~200 ms shorter sounds are harder to detect.",section:"§5.5 Auditory Perception"},hf_hearing_loss_definition_hl:{name:"Hearing-loss threshold criterion",value:25,unit:"dB HL (>)",kind:"limit",group:"Audition — hearing loss",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.2",page:160,applicability:"general",quote:"Hearing loss is generally defined by thresholds that are greater than about 25 dB HL",note:"Thresholds above 25 dB HL indicate hearing loss.",section:"§5.5 Auditory Perception"},hf_normal_hearing_range_hl:{name:"Normal hearing range",value:null,unit:"dB HL (-10 to 25)",kind:"threshold",group:"Audition — hearing loss",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.2",page:160,applicability:"general",quote:"normal hearing ranging from -10 dB HL to 25 dB HL",note:"Normal audiometric thresholds span -10 to 25 dB HL.",section:"§5.5 Auditory Perception"},hf_hearing_loss_prevalence_61_71_20db:{name:"Prevalence of >20 dB loss, age 61-71",value:51,unit:"%",kind:"error-rate",group:"Audition — hearing loss",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.2 Table 5.5-2 (ACOEM 2003)",page:161,applicability:"general",quote:"61-71 ... 51 ... [Hearing Loss > 20 dB]",note:"Loss averaged over 500,1000,2000,4000 Hz.",section:"§5.5 Auditory Perception"},hf_hearing_loss_prevalence_71_80_40db:{name:"Prevalence of >40 dB loss, age 71-80",value:30,unit:"%",kind:"error-rate",group:"Audition — hearing loss",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.2 Table 5.5-2 (ACOEM 2003)",page:161,applicability:"general",quote:"71-80 ... 30 ... [Hearing Loss > 40 dB]",note:"Loss averaged over 500,1000,2000,4000 Hz.",section:"§5.5 Auditory Perception"},hf_nihl_notch_frequencies:{name:"Noise-induced hearing-loss notch frequencies",value:null,unit:"Hz (3000–6000)",kind:"degradation",group:"Audition — hearing loss",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.2",page:161,applicability:"general",quote:"an elevation of hearing thresholds at 3000, 4000, or 6000 Hz, with recovery at 8000 Hz",note:"First sign of NIHL is a notch at 3–6 kHz with 8 kHz recovery.",section:"§5.5 Auditory Perception"},hf_who_no_loss_leq8h:{name:"WHO no-hearing-loss limit (8-h)",value:75,unit:"dBA",kind:"design-limit",group:"Audition — noise exposure",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.2 (Berglund et al. 1999 / WHO)",page:162,applicability:"general",quote:"hearing loss is not expected to occur at LAeq, 8h levels of 75 dBA or lower",note:"WHO occupational-noise safe level, 8-h.",section:"§5.5 Auditory Perception"},hf_who_no_impairment_leq24h:{name:"WHO no-impairment limit (24-h)",value:70,unit:"dBA",kind:"design-limit",group:"Audition — noise exposure",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.2 (Berglund et al. 1999 / WHO)",page:162,applicability:"general",quote:"noise with an LAeq, 24h of 70 dBA or lower will not cause hearing impairment in the large majority of people",note:"Lifetime environmental/leisure noise safe level.",section:"§5.5 Auditory Perception"},hf_tts_rapid_onset_level:{name:"Level above which temporary threshold shift rises rapidly",value:null,unit:"dBA (90–100)",kind:"limit",group:"Audition — noise exposure",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.2",page:162,applicability:"general",quote:"threshold shift, which is generally small for lower exposure levels, but increases rapidly for sounds above 90 to 100 dBA",note:"TTS grows rapidly above 90–100 dBA.",section:"§5.5 Auditory Perception"},hf_pts_single_exposure_level:{name:"Single-exposure level likely to cause permanent shift",value:null,unit:"dBA (110–120)",kind:"limit",group:"Audition — noise exposure",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.2",page:162,applicability:"general",quote:"Single exposures to levels above 110 to 120 dBA are likely to produce PTS",note:"Permanent threshold shift risk from single exposure.",section:"§5.5 Auditory Perception"},hf_loudness_power_exponent:{name:"Loudness-vs-pressure power exponent",value:.6,unit:"exponent",kind:"threshold",group:"Audition — loudness",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.3",page:163,applicability:"general",quote:"perceived loudness of a sound is proportional to its RMS sound pressure raised to the power of 0.6",note:"Subjective loudness scales as pressure^0.6.",section:"§5.5 Auditory Perception"},hf_loudness_doubling_per_10db:{name:"Perceived-loudness growth per 10 dB",value:16,unit:"× (per +40 dB)",kind:"threshold",group:"Audition — loudness",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.3",page:163,applicability:"general",quote:"an 80-dB SPL sound is not twice as loud as a 40-dB sound, rather it is perceived as about 16 times louder",note:"Loudness roughly doubles per 10 dB increase.",section:"§5.5 Auditory Perception"},hf_loudness_duration_integration:{name:"Loudness increases with duration up to",value:null,unit:"ms (100–200)",kind:"latency",group:"Audition — loudness",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.3",page:164,applicability:"general",quote:"loudness will increase with increasing duration up to about 100 to 200 ms",note:"Loudness temporal integration window.",section:"§5.5 Auditory Perception"},hf_intensity_jnd_wideband:{name:"Intensity JND for wideband noise",value:.4,unit:"dB (~10%)",kind:"threshold",group:"Audition — intensity discrimination",source:"NASA/SP-2010-3407 (HIDH) §5.5.3.5",page:164,applicability:"general",quote:"approximately a +0.4-dB change in level corresponds to a 10% increase from the baseline level",note:"Constant ~0.4 dB JND over 30–110 dB SPL baseline.",section:"§5.5 Auditory Perception"},hf_erb_fraction_of_center_freq:{name:"Auditory filter ERB above 1000 Hz",value:null,unit:"% of center freq (10–17)",kind:"threshold",group:"Audition — masking",source:"NASA/SP-2010-3407 (HIDH) §5.5.4.1 (Moore 2004)",page:166,applicability:"general",quote:"For frequencies above 1000 Hz, the ERB of normal listeners is about 10% to 17% of the center frequency",note:"Critical-band width scales with center frequency.",section:"§5.5 Auditory Perception"},hf_frequency_discrimination_jnd_low:{name:"Frequency-discrimination JND at/below 4000 Hz",value:null,unit:"% of freq (0.1–0.2)",kind:"threshold",group:"Audition — frequency discrimination",source:"NASA/SP-2010-3407 (HIDH) §5.5.4.3 (Plack 2005)",page:168,applicability:"general",quote:"for tones of 4000 Hz or below, the JND is on the order of 0.1% to 0.2% of the frequencies being compared",note:"E.g., 1000 Hz vs 1002 Hz just discriminable.",section:"§5.5 Auditory Perception"},hf_pitch_existence_region:{name:"Existence region of pitch",value:null,unit:"Hz (30–5000)",kind:"threshold",group:"Audition — pitch",source:"NASA/SP-2010-3407 (HIDH) §5.5.4.4",page:169,applicability:"general",quote:"the existence region for pitch ranges from about 30 to 5000 Hz",note:"Outside 30–5000 Hz repetition rate no longer yields pitch.",section:"§5.5 Auditory Perception"},hf_itd_phase_ambiguity_limit:{name:"Frequency above which ITD phase ambiguity occurs",value:1500,unit:"Hz",kind:"limit",group:"Audition — localization",source:"NASA/SP-2010-3407 (HIDH) §5.5.5.1",page:170,applicability:"general",quote:"the phase ambiguities occurring at frequencies greater than 1500 Hz",note:"Interaural time-difference cue reliable mainly below 1500 Hz.",section:"§5.5 Auditory Perception"},hf_localization_blur:{name:"Localization blur (resolution error)",value:null,unit:"° (5–20)",kind:"threshold",group:"Audition — localization",source:"NASA/SP-2010-3407 (HIDH) §5.5.5.2 (Blauert 1983)",page:172,applicability:"general",quote:"localization blur, is a relatively small error in resolution on the order of about 5° to 20°",note:"Typical static-source localization error.",section:"§5.5 Auditory Perception"},hf_minimum_audible_angle:{name:"Minimum audible angle (MAA)",value:1,unit:"° (1 front to 20+ side)",kind:"threshold",group:"Audition — localization",source:"NASA/SP-2010-3407 (HIDH) §5.5.5.2",page:172,applicability:"general",quote:"MAAs increase from about 1° for a sound straight ahead to 20° or more for a sound directly to the right or left",note:"Best angular resolution (1°) is straight ahead.",section:"§5.5 Auditory Perception"},hf_absolute_identification_limit:{name:"Absolute identification limit (single dimension)",value:null,unit:"sounds (<5–6)",kind:"capacity",group:"Audition — nonspeech",source:"NASA/SP-2010-3407 (HIDH) §5.5.6.1 (Pollack 1952)",page:173,applicability:"general",quote:"listeners are able to name and identify a particular sound only when the total number of sounds in the set is less than about 5 or 6",note:"Absolute identification along one dimension caps at ~5–6 items; limits distinct alarm tones.",section:"§5.5 Auditory Perception"},hf_stream_segregation_frequency_separation:{name:"Frequency separation for tone-stream segregation",value:7,unit:"semitones",kind:"capacity",group:"Audition — nonspeech",source:"NASA/SP-2010-3407 (HIDH) §5.5.6.1",page:175,applicability:"general",quote:"the frequency difference between alternating tones is not large enough to clearly signal different sound streams (about 7 semitones)",note:"~7 semitones is the ambiguous one-vs-two-stream boundary.",section:"§5.5 Auditory Perception"},hf_speech_fricative_energy_band:{name:"High-frequency energy band of fricatives/plosives",value:null,unit:"Hz (4000–8000)",kind:"threshold",group:"Audition — speech",source:"NASA/SP-2010-3407 (HIDH) §5.5.6.2",page:175,applicability:"general",quote:'fricative phonemes like "f" and plosive phonemes like "t" have considerable energy in the higher frequency range from 4000 to 8000 Hz',note:"Consonant discrimination depends on 4–8 kHz energy.",section:"§5.5 Auditory Perception"},hf_communication_bandwidth_requirement:{name:"Communication bandwidth needed for consonant discrimination",value:null,unit:"Hz (up to 7000–8000)",kind:"design-limit",group:"Audition — speech",source:"NASA/SP-2010-3407 (HIDH) §5.5.6.2",page:175,applicability:"general",quote:"communication systems must be designed to transmit frequencies up to about 7000 to 8000 Hz",note:"Below this, consonant confusions and miscommunication rise.",section:"§5.5 Auditory Perception"},hf_telephone_speech_cutoff:{name:"Standard telephone speech cutoff",value:3500,unit:"Hz",kind:"design-limit",group:"Audition — speech",source:"NASA/SP-2010-3407 (HIDH) §5.5.6.2",page:175,applicability:"general",quote:"standard telephone speech that cuts off at 3500 Hz",note:"Legacy 3500 Hz cutoff raises repetition/quality problems.",section:"§5.5 Auditory Perception"},hf_simple_rt_light_stimulus:{name:"Mean simple reaction time to light (visual) stimulus",value:190,unit:"ms",kind:"latency",group:"Cognition — reaction time",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.1 (Galton 1899; Welford 1980)",page:180,applicability:"general",quote:"mean simple reaction times for college-age individuals have been about 190 ms (0.19 s) for light stimuli",note:"Mean simple RT to a visual stimulus for college-age adults.",section:"§5.6 Cognition"},hf_simple_rt_sound_stimulus:{name:"Mean simple reaction time to sound (auditory) stimulus",value:160,unit:"ms",kind:"latency",group:"Cognition — reaction time",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.1 (Galton 1899; Welford 1980)",page:180,applicability:"general",quote:"about 190 ms (0.19 s) for light stimuli and about 160 ms for sound stimuli",note:"Mean simple RT to an auditory stimulus, faster than visual.",section:"§5.6 Cognition"},hf_reaction_time_touch:{name:"Reaction time to touch (tactile) stimulus",value:155,unit:"ms",kind:"latency",group:"Cognition — reaction time",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.1 (Robinson 1934)",page:180,applicability:"general",quote:"Reaction time to touch is intermediate, at 155 ms (Robinson, 1934)",note:"Tactile RT falls between auditory and visual.",section:"§5.6 Cognition"},hf_auditory_signal_transit_to_brain:{name:"Auditory stimulus transmission time to the brain",value:null,unit:"ms (8–10)",kind:"latency",group:"Cognition — reaction time",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.1 (Kemp 1973)",page:180,applicability:"general",quote:"an auditory stimulus takes only 8 to 10 ms to reach the brain (Kemp, 1973)",note:"Explains why auditory RT beats visual RT.",section:"§5.6 Cognition"},hf_visual_signal_transit_to_brain:{name:"Visual stimulus transmission time to the brain",value:null,unit:"ms (20–40)",kind:"latency",group:"Cognition — reaction time",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.1 (Marshall et al. 1943)",page:180,applicability:"general",quote:"a visual stimulus takes 20 to 40 ms (Marshall et al., 1943)",note:"Slower than auditory transmission.",section:"§5.6 Cognition"},hf_memory_search_rt_per_item:{name:"RT increase per added memory-set item (Sternberg)",value:40,unit:"ms/item",kind:"latency",group:"Cognition — reaction time",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.1 (Sternberg 1969)",page:180,applicability:"general",quote:"increasing by about 40 ms every time another item was added to the memory set",note:"RT rises proportional to memory-set size in recognition tasks.",section:"§5.6 Cognition"},hf_visual_sensory_store_duration:{name:"Visual short-term sensory register persistence",value:300,unit:"ms",kind:"threshold",group:"Cognition — sensory memory",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.2 (Sperling 1960)",page:182,applicability:"general",quote:"Vision… ......... 300 ms (Sperling, 1960)",note:"Permit ≥300 ms before replacing visual info to avoid masking.",section:"§5.6 Cognition"},hf_auditory_sensory_store_duration:{name:"Auditory short-term sensory register persistence",value:20,unit:"s",kind:"threshold",group:"Cognition — sensory memory",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.2 (Watkins & Watkins 1980)",page:182,applicability:"general",quote:"Audition………20 s (Watkins & Watkins, 1980)",note:"Auditory sensory trace lasts far longer than the visual trace.",section:"§5.6 Cognition"},hf_change_blindness_still_image_interval:{name:"Change-blindness interval for still images",value:13,unit:"s",kind:"threshold",group:"Cognition — attention",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.2 (Rensink et al. 1997)",page:182,applicability:"general",quote:"change blindness can be achieved by changing a part of the image within 13 seconds or longer",note:"Gradual changes over ≥13 s go undetected; display changes may not be noticed.",section:"§5.6 Cognition"},hf_change_blindness_display_off_duration:{name:"Minimum display-off duration inducing change blindness",value:67,unit:"ms",kind:"threshold",group:"Cognition — attention",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.2 (Pashler 1988)",page:182,applicability:"general",quote:"a display being turned off even as briefly as 67 ms (Pashler, 1988)",note:"A blank as short as 67 ms during a change can trigger change blindness.",section:"§5.6 Cognition"},hf_working_memory_capacity_classic:{name:"Working-memory capacity (classic estimate)",value:null,unit:"chunks (5–9)",kind:"capacity",group:"Cognition — working memory",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.4 (Miller 1956)",page:185,applicability:"general",quote:"the number of working memory chunks to be from five to nine in adults (Miller, 1956)",note:"Classic 7±2 range for adults.",section:"§5.6 Cognition"},hf_working_memory_capacity_recent:{name:"Working-memory capacity (recent estimate)",value:4,unit:"chunks",kind:"capacity",group:"Cognition — working memory",source:"NASA/SP-2010-3407 (HIDH) §5.6.3.4 (Cowan 2001)",page:185,applicability:"general",quote:"More recent research estimates that number to be about four in young adults (Cowan, 2001)",note:"Lower modern estimate of usable WM chunks.",section:"§5.6 Cognition"},hf_astronaut_orbit_sleep_duration:{name:"Actual sleep obtained by astronauts in orbit",value:6,unit:"hours/day",kind:"degradation",group:"Cognition — fatigue/sleep",source:"NASA/SP-2010-3407 (HIDH) §5.6.4 (Monk et al. 1998)",page:193,applicability:"spaceflight",quote:"astronauts commonly experience sleep disruption, sleeping only approximately 6 hours per day in orbit",note:"Chronic in-orbit sleep restriction.",section:"§5.6 Cognition"},hf_chronic_sleep_restriction_impairment:{name:"Chronic sleep restriction causing cognitive impairment",value:6,unit:"hours/day",kind:"degradation",group:"Cognition — fatigue/sleep",source:"NASA/SP-2010-3407 (HIDH) §5.6.4 (Van Dongen et al. 2003)",page:193,applicability:"general",quote:"chronic reduction of sleep to 6 hours per day leads to cognitive performance impairment (Van Dongen et al., 2003)",note:"Lab-demonstrated cognitive decrement from sustained 6 h/day sleep.",section:"§5.6 Cognition"},hf_time_occupancy_red_line_pct:{name:"Time-occupancy Red Line (timeline analysis)",value:80,unit:"% of available time",kind:"threshold",group:"Workload — Red Line thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.7.5.1 (Parks & Boucek 1989)",page:229,applicability:"general",quote:'when a task requires 80% of the available time on a timeline, this defines a "Red Line"',note:"Time-Line Analysis red line; errors begin when time-occupancy exceeds 80%.",section:"§5.7 Cognitive Workload"},hf_imprint_red_line_default:{name:"IMPRINT default workload Red Line",value:60,unit:"IMPRINT workload units",kind:"threshold",group:"Workload — Red Line thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.7.4.2.5 (Mitchell et al. 2003)",page:228,applicability:"general",quote:'dynamic simulation models can accommodate user-specified "Red Lines" and offer a default value (e.g., 60 in IMPRINT)',note:"Default (unvalidated) multitask overload Red Line in IMPRINT.",section:"§5.7 Cognitive Workload"},hf_swat_unacceptable_threshold:{name:"SWAT unacceptable-performance threshold",value:40,unit:"SWAT rating (0–100)",kind:"threshold",group:"Workload — Red Line thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.7.5.2 (Colle & Reid 2005)",page:230,applicability:"general",quote:"SWAT values above a rating of 40 produce an unacceptable loss of performance",note:"SWAT cutoff for unacceptable performance; noted as not well validated.",section:"§5.7 Cognitive Workload"},hf_nasatlx_unacceptable_threshold:{name:"NASA-TLX unacceptable time-sharing threshold",value:60,unit:"NASA-TLX rating (1–100)",kind:"threshold",group:"Workload — Red Line thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.7.5.2 (Moray & Liao)",page:230,applicability:"general",quote:"a NASA-TLX rating above 60 produced unacceptable time-sharing behavior",note:"NASA-TLX cutoff for unacceptable multitask performance; not well validated.",section:"§5.7 Cognitive Workload"},hf_working_memory_red_line_chunks:{name:"Working-memory-load Red Line",value:5,unit:"chunks (conservatively 4)",kind:"threshold",group:"Workload — working memory",source:"NASA/SP-2010-3407 (HIDH) §5.7.5.1",page:230,applicability:"general",quote:'One could thus define a "Red Line" at 5, or conservatively at 4',note:"Working-memory Red Line; summary states 'less than 5 chunks'.",section:"§5.7 Cognitive Workload"},hf_working_memory_capacity_chunks_57:{name:"Working memory capacity (workload context)",value:null,unit:"chunks (5–7)",kind:"capacity",group:"Workload — working memory",source:"NASA/SP-2010-3407 (HIDH) §5.7.5.1 (Miller 1956; Card, Moran & Newell 1983)",page:229,applicability:"general",quote:'the capacity of working memory is somewhere in the range of 5 to 7 "chunks" of information',note:"Demands greater than 5–7 chunks likely produce errors of memory.",section:"§5.7 Cognitive Workload"},hf_relational_complexity_red_line:{name:"Relational (cognitive) complexity Red Line",value:null,unit:"elements (between 3 and 4)",kind:"threshold",group:"Workload — Red Line thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.7.5.1 (Halford et al. 1995, 2002; Boag et al. 2006)",page:230,applicability:"general",quote:"a discontinuity of performance speed and accuracy somewhere between three and four elements, indicating an upper workload boundary",note:"Cognitive-complexity Red Line; summary states 'complexity less than 4'.",section:"§5.7 Cognitive Workload"},hf_bedford_red_line_rating:{name:"Bedford scale unacceptable-workload rating",value:6,unit:"Bedford rating (1–10)",kind:"threshold",group:"Workload — Red Line thresholds",source:"NASA/SP-2010-3407 (HIDH) §5.7.5.2 (Roscoe 1987)",page:230,applicability:"aircraft",quote:'a rating equal to or greater than 6 deemed "above the Red Line" and thus unacceptable',note:"Bedford '6' = satisfactory but little spare capacity; ≥6 above Red Line.",section:"§5.7 Cognitive Workload"},hf_bedford_red_line_reserve_capacity:{name:"Bedford scale Red Line (zero reserve capacity)",value:0,unit:"reserve capacity",kind:"threshold",group:"Workload — rating scales",source:"NASA/SP-2010-3407 (HIDH) §5.7.3.4.1.2.3 (Roscoe 1987)",page:217,applicability:"aircraft",quote:'the Bedford scale provides an option that explicitly identifies a "Red Line" level of workload (0 reserve capacity)',note:"Bedford decision-tree scale explicitly marks the zero-spare-capacity Red Line.",section:"§5.7 Cognitive Workload"},hf_nasatlx_arbitrary_red_line_mean:{name:"NASA-TLX arbitrary Red Line standard",value:5,unit:"mean NASA-TLX rating",kind:"threshold",group:"Workload — rating scales",source:"NASA/SP-2010-3407 (HIDH) §5.7.5",page:229,applicability:"general",quote:"establish a somewhat arbitrary standard along a workload ... scale, so as to define a mean rating of 5 on the NASA-TLX scales",note:"Example of an arbitrary subjective-scale Red Line standard.",section:"§5.7 Cognitive Workload"},hf_nasatlx_subscale_count:{name:"NASA-TLX number of subscales",value:6,unit:"subscales",kind:"design-limit",group:"Workload — rating scales",source:"NASA/SP-2010-3407 (HIDH) §5.7.3.4.1.3.2 (Hart & Staveland 1988)",page:218,applicability:"general",quote:"an estimate of overall workload based on a weighted average of six subscale ratings",note:"Mental, Physical, Temporal Demand, Own Performance, Effort, Frustration.",section:"§5.7 Cognitive Workload"},hf_swat_global_score_range:{name:"SWAT global workload score range",value:null,unit:"0–27 (rescaled to 100)",kind:"design-limit",group:"Workload — rating scales",source:"NASA/SP-2010-3407 (HIDH) §5.7.3.4.1.3.1 (Reid 1985; Nygren 1991)",page:218,applicability:"general",quote:"assigned a numerical (global workload) value ranging from 0 to 27",note:"27 combinations of 3 subscales × 3 levels.",section:"§5.7 Cognitive Workload"},hf_cooper_harper_scale_range:{name:"Cooper-Harper rating range",value:null,unit:"1–10 rating",kind:"design-limit",group:"Workload — rating scales",source:"NASA/SP-2010-3407 (HIDH) §5.7.3.4.1.2.1 (Cooper & Harper 1969)",page:216,applicability:"aircraft",quote:"Each decision leads the rater to another choice or to a final numeric rating ranging from 1 to 10",note:"Decision-tree handling-qualities scale.",section:"§5.7 Cognitive Workload"},hf_mccracken_aldrich_scale_max:{name:"McCracken & Aldrich workload demand scale",value:7,unit:"workload units (0–7), 7 channels",kind:"design-limit",group:"Workload — task demand",source:"NASA/SP-2010-3407 (HIDH) §5.7.4.1 (McCracken & Aldrich 1984; Aldrich et al. 1989)",page:221,applicability:"general",quote:"different tasks are defined along a scale of workload values ranging from 0 to a maximum of 7",note:"Seven workload channels each scored 0–7 (Table 5.7-2).",section:"§5.7 Cognitive Workload"},hf_mccracken_combined_track_read:{name:"Summed visual workload (track + read symbol)",value:9.5,unit:"workload units",kind:"capacity",group:"Workload — task demand",source:"NASA/SP-2010-3407 (HIDH) §5.7.4.1 (McCracken & Aldrich 1984)",page:225,applicability:"general",quote:"the visual workload (Table 5.7-2) imposed by the task combination of tracking (4.4) while reading a symbol (5.1) is 9.5",note:"Within-channel summed workload example (tracking 4.4 + reading 5.1).",section:"§5.7 Cognitive Workload"},hf_multiple_resource_interference_range:{name:"Static multiple-resource model total interference range",value:null,unit:"index 0–8",kind:"design-limit",group:"Workload — multiple-resource model",source:"NASA/SP-2010-3407 (HIDH) §5.7.4.2.2 (Wickens 2002, 2005)",page:226,applicability:"general",quote:"provide a predicted total interference measure that could range from 0 to 8",note:"Total demand (0–4) plus resource-conflict (0–4).",section:"§5.7 Cognitive Workload"},hf_red_line_response_criterion:{name:"Red Line response-time performance criterion",value:1,unit:"second",kind:"threshold",group:"Workload — performance criteria",source:"NASA/SP-2010-3407 (HIDH) §5.7.2.2",page:203,applicability:"general",quote:'Performance remains "perfect" ... such as a response within 1 second, or flight path tracking within 1 meter',note:"Illustrative acceptable-performance criterion left of the Red Line.",section:"§5.7 Cognitive Workload"},hf_hrv_low_frequency:{name:"Low-frequency heart-rate-variability workload band",value:.1,unit:"Hz (~10-s cycle)",kind:"capacity",group:"Workload — physiological measures",source:"NASA/SP-2010-3407 (HIDH) §5.7.3.3.2 (Table 5.7-1; Veltman & Verwey 1996)",page:214,applicability:"general",quote:"Heart rate normally waxes and wanes at a cycle time of around 10 seconds (0.10 Hz)",note:"0.10 Hz HRV declines with higher cognitive load; noninvasive workload index.",section:"§5.7 Cognitive Workload"},hf_crew_time_audio_terminal_travel:{name:"Crew time lost traveling to audio terminal units (ISS)",value:6,unit:"hours/week",kind:"limit",group:"Coordination — communication overhead",source:"NASA/SP-2010-3407 (HIDH) §5.8.4.4.2 (Baggerman, Rando & Duvall 2004)",page:267,applicability:"spaceflight",quote:"An estimated six hours per week of crew time is spent moving to audio terminal units to facilitate communication.",note:"Weekly crew time consumed relocating to fixed comm terminals on ISS.",section:"§5.8 Crew Coordination & Collaboration"},hf_alarm_ack_delay_ground_contact:{name:"Delay to contact ground during drills/alarms",value:30,unit:"minutes (20–30)",kind:"latency",group:"Coordination — communication overhead",source:"NASA/SP-2010-3407 (HIDH) §5.8.4.4.2 (Baggerman, Rando & Duvall 2004)",page:267,applicability:"spaceflight",quote:"acknowledging the alarms, which can take up to 20 to 30 minutes",note:"Crew must acknowledge alarms first, delaying ground contact.",section:"§5.8 Crew Coordination & Collaboration"},hf_intl_crew_miscommunication_incidents:{name:"Miscommunication/conflict incidents per international-crew mission",value:5,unit:"incidents/mission",kind:"error-rate",group:"Coordination — team communication errors",source:"NASA/SP-2010-3407 (HIDH) §5.8.3.1.4.2 (Santy 1993)",page:249,applicability:"spaceflight",quote:"revealed an average of five incidents involving miscommunication, misunderstanding, and interpersonal conflict",note:"U.S. astronauts flying a Shuttle mission with one international crewmember.",section:"§5.8 Crew Coordination & Collaboration"},hf_miscommunication_incidents_high_impact_pct:{name:"Miscommunication incidents rated moderate/high mission impact",value:57,unit:"%",kind:"error-rate",group:"Coordination — team communication errors",source:"NASA/SP-2010-3407 (HIDH) §5.8.3.1.4.2 (Santy 1993)",page:249,applicability:"spaceflight",quote:"Moreover, 57% of these incidents were rated as having had a moderate or high impact on the mission",note:"Fraction of incidents judged to materially affect the mission.",section:"§5.8 Crew Coordination & Collaboration"},hf_optimal_group_decision_size:{name:"Optimal group size for discussion/decision-making",value:5,unit:"members",kind:"design-limit",group:"Coordination — crew size",source:"NASA/SP-2010-3407 (HIDH) §5.8.4.1.3 (Hackman & Vidmar 1970; Hare 1982)",page:254,applicability:"general",quote:"An optimal size for group discussion and decision-making is around five members",note:"Crew-size effect; optimum is task-dependent.",section:"§5.8 Crew Coordination & Collaboration"},hf_task_conflict_team_performance_corr:{name:"Task conflict correlation with team performance",value:-.23,unit:"correlation r",kind:"degradation",group:"Coordination — team conflict",source:"NASA/SP-2010-3407 (HIDH) §5.8.3.1.1 Table 5.8-1 (De Dreu & Weingart 2003)",page:246,applicability:"general",quote:"Team Performance | Task Conflict -0.23 | Relationship Conflict -0.22",note:"Meta-analytic negative correlation with performance.",section:"§5.8 Crew Coordination & Collaboration"},hf_relationship_conflict_satisfaction_corr:{name:"Relationship conflict correlation with team-member satisfaction",value:-.54,unit:"correlation r",kind:"degradation",group:"Coordination — team conflict",source:"NASA/SP-2010-3407 (HIDH) §5.8.3.1.1 Table 5.8-1 (De Dreu & Weingart 2003)",page:246,applicability:"general",quote:"Team Member Satisfaction | Task Conflict -0.32 | Relationship Conflict -0.54",note:"Relationship conflict strongly lowers team-member satisfaction.",section:"§5.8 Crew Coordination & Collaboration"},hf_accel_transient_duration_boundary:{name:"Transient acceleration duration boundary",value:.5,unit:"s",kind:"threshold",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:398,applicability:"general",quote:"Transient accelerations, translational or rotational, are events with a duration of less than or equal to 0.5 seconds.",note:"Defines the sustained/transient split.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_rotational_accel_sustained_limit:{name:"Sustained rotational acceleration limit",value:115,unit:"deg/s^2",kind:"design-limit",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:402,applicability:"spaceflight",quote:"sustained rotational accelerations must not exceed 115°/s2 in yaw, pitch, or roll.",note:"Protects against severe discomfort and disorientation.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_rotation_rate_tolerable_any_axis:{name:"Rotation rate tolerable in any axis (untrained)",value:6,unit:"rpm",kind:"threshold",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:401,applicability:"spaceflight",quote:"6 rpm ... Most individuals without previous experience can tolerate this rotation in any axis",note:"Above 6 rpm most become sick/disoriented unless trained.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_accel_rate_of_change_limit:{name:"Rate of change of acceleration (jerk) limit",value:500,unit:"g/s",kind:"design-limit",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:410,applicability:"spaceflight",quote:"the crew must be prevented from being exposed to a rate of change of acceleration of more than 500 g/s during any sustained acceleration event.",note:"Onset-rate cap to reduce incapacitation risk.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_gz_grayout_onset:{name:"+Gz grayout / vision-dimming onset",value:3,unit:"g",kind:"degradation",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:406,applicability:"general",quote:"+3 to +4g | ... progressive dimming of vision (grayout) after 3–4 seconds",note:"Sustained +Gz, relaxed unprotected subject.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_gz_blackout_onset:{name:"+Gz blackout / loss of consciousness onset",value:4,unit:"g",kind:"threshold",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:406,applicability:"general",quote:"+4 to +6g | Total loss of vision (blackout) after about 5 seconds; hearing and then consciousness lost",note:"Sustained +Gz; protection required above +6g.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_gz_protection_required:{name:"+Gz level requiring protection",value:6,unit:"g",kind:"design-limit",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:406,applicability:"general",quote:"> +6g | Protection is needed to preserve health",note:"Sustained +Gz eyeballs-down threshold for mandatory protection.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_neg_gz_tolerance_limit:{name:"-Gz tolerance limit (5-second)",value:-3,unit:"g",kind:"threshold",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:406,applicability:"general",quote:"> –3 Gz | The 5-second tolerance limit is rarely reached; causes mental confusion and unconsciousness",note:"Negative Gz; -2 to -3 Gz causes severe facial congestion and bradycardia.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_gx_tolerable_24h:{name:"+Gx tolerable for at least 24 hours",value:2,unit:"g",kind:"capacity",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:407,applicability:"general",quote:"+2 to +3x | Difficulty in spatial orientation; +2g tolerable for at least 24 hours",note:"Sustained +Gx (eyeballs in); best-tolerated direction.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_gx_tolerable_60min:{name:"+Gx tolerable up to at least 60 minutes",value:4,unit:"g",kind:"capacity",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:407,applicability:"general",quote:"+3 to +6x | ... 4g tolerable up to at least 60 minutes",note:"Sustained +Gx eyeballs-in.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_gx_o2_desaturation:{name:"+Gx arterial O2 desaturation / cognitive impairment onset",value:6,unit:"g",kind:"degradation",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:407,applicability:"general",quote:"+6 to +9x | ... arterial oxygen saturation falls below 85%, which can lead to cognitive impairment",note:"Body cannot be lifted at +8g; head cannot be lifted at +9g.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_gy_discomfort_onset:{name:"±Gy discomfort onset",value:3,unit:"g",kind:"degradation",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:407,applicability:"general",quote:"+/–3y | Discomfort after 10 seconds; ... total body restraint system is critical",note:"Lateral Gy; ±5Gy has produced conjunctival hemorrhage.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_impact_tolerance_gx_chest:{name:"Impact tolerance ±Gx (chest)",value:20,unit:"g (rate 10,000 g/s)",kind:"limit",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:414,applicability:"general",quote:"± Gx (chest) | 20g | 10,000g/s",note:"Impact tolerance without serious injury (Table 6.5-7).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_impact_tolerance_gz_spine:{name:"Impact tolerance ±Gz (spine)",value:15,unit:"g (rate 500 g/s)",kind:"limit",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:414,applicability:"general",quote:"± Gz (spine) | 15g | 500g/s",note:"Spine is the most vulnerable axis (Table 6.5-7).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_ejection_seat_accel:{name:"Aircraft ejection seat firing acceleration",value:17,unit:"Gz (up to)",kind:"limit",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5 (MIL-S-18471G 1983)",page:414,applicability:"aircraft",quote:"Aircraft ejection seat firing | up to 17 Gz*",note:"Aircraft transient acceleration level (Table 6.5-6).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_crash_landing_accel:{name:"Aircraft crash landing acceleration",value:10,unit:"g (10 to >100g)",kind:"limit",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:414,applicability:"aircraft",quote:"Crash landing | 10g to greater than 100g (omnidirectional)",note:"Aircraft transient level, lower bound (Table 6.5-6).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_parachute_opening_shock:{name:"Parachute-opening shock acceleration",value:10,unit:"Gz (~)",kind:"limit",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:414,applicability:"aircraft",quote:"Parachute-opening shock | approximately 10 Gz",note:"Aircraft transient acceleration level (Table 6.5-6).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_muscle_contraction_tolerance_gain:{name:"G-tolerance gain from sustained muscle contraction",value:2,unit:"g",kind:"capacity",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5 (von Diringshofen 1942)",page:412,applicability:"general",quote:"sustained contraction of all the skeletal muscles increased tolerance by approximately 2g",note:"Anti-G straining countermeasure benefit for short exposures.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_orion_control_reach_limit:{name:"Acceleration above which controls must be operable without reaching",value:3,unit:"g",kind:"design-limit",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5",page:412,applicability:"spaceflight",quote:"controls used during accelerations above 3 g be operable without reaching, and between 2g and 3g ... hand/wrist movements",note:"Constellation/Orion requirement; limb support required 2-3 g.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_brinkley_beta_limit:{name:"Brinkley injury-risk criterion (beta) limit",value:1,unit:"dimensionless",kind:"design-limit",group:"Environment — acceleration",source:"NASA/SP-2010-3407 (HIDH) §6.5 (Brinkley et al. 1990)",page:416,applicability:"spaceflight",quote:"the injury risk criterion, β, which must be limited to no greater than 1.0",note:"Combined-axis transient injury metric.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_speech_normal_level_1m:{name:"Normal speech level at 1 meter (male)",value:58,unit:"dBA",kind:"capacity",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6 (Berger 2003)",page:439,applicability:"general",quote:"normal | 58 | 55",note:"Average A-weighted male/female normal vocal effort at 1 m; shout 89/82 dBA.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_speech_shout_level_1m:{name:"Shouted speech level at 1 meter (male)",value:89,unit:"dBA",kind:"capacity",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6 (Berger 2003)",page:439,applicability:"general",quote:"shout | 89 | 82",note:"Maximum vocal effort at 1 m (Table 6.6-1).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_speech_snr_optimal:{name:"Signal-to-noise ratio for intelligible speech",value:10,unit:"dB",kind:"threshold",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6",page:440,applicability:"general",quote:"at least a 10-dB signal-to-noise ratio in the frequency region of speech (200 Hz–7 kHz) is optimal ... (approximately 90% word recognition)",note:"Applies over 200 Hz-7 kHz speech band.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_just_perceptible_noise_change:{name:"Just-perceptible change in noise level",value:3,unit:"dB",kind:"threshold",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6",page:439,applicability:"general",quote:"humans can just perceive a 3dB change in noise, but this is the equivalent of doubling or halving of acoustic power",note:"Motivates reliance on quantitative measurement.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_noise_dose_limit_twa:{name:"Noise exposure dose limit (8-hr TWA over 24 h)",value:85,unit:"dBA",kind:"design-limit",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6 (NIOSH 1998)",page:444,applicability:"spaceflight",quote:"noise exposure level at the crewmember's ear ... must be limited to 85 dBA, 8-hour time-weighted average, using a 3-dB energy exchange rate",note:"Hearing-conservation limit.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_hazardous_noise_limit:{name:"Hazardous noise level limit (any duration)",value:115,unit:"dBA",kind:"design-limit",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6 (NIOSH 1990)",page:445,applicability:"spaceflight",quote:"the noise level at crew ear locations must be limited to a maximum of 115 dBA for any duration",note:"Also max level for personal communication devices at the ear.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_continuous_noise_work_area_nc:{name:"Continuous-noise limit for work/habitable areas (NC curve)",value:50,unit:"NC",kind:"design-limit",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6",page:446,applicability:"spaceflight",quote:"sound pressure levels of continuous noise should be limited to the values given by the NC-50 curve",note:"NC-50 gives >75% key-word intelligibility at 5-8 ft; adopted for ISS.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_continuous_noise_sleep_max_nc:{name:"Continuous-noise maximum for sleep areas (NC curve)",value:40,unit:"NC",kind:"design-limit",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6",page:448,applicability:"spaceflight",quote:"For crew quarters and sleep areas, sound pressure levels of continuous noise should be limited to the values given by the NC-40 curve as a maximum",note:"A minimum of NC-25 is also recommended for restful sleep.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_reverberation_time_limit:{name:"Maximum reverberation time (1 kHz octave band)",value:.5,unit:"s",kind:"design-limit",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6",page:450,applicability:"spaceflight",quote:"A maximum reverberation time of 0.5 seconds (with a tolerance of +0.1s, –0.3s) must be provided in the 1 kHz octave band",note:"For rooms of ~100 m^3; preserves speech intelligibility.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_impulse_noise_limit:{name:"Impulse noise peak SPL limit",value:140,unit:"dB peak",kind:"design-limit",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6 (MIL-STD-1474D 1997)",page:451,applicability:"spaceflight",quote:"Space flight hardware must limit impulse noise measured at the crewmember's ears to less than 140 dB peak sound pressure level.",note:"Prevents acoustic trauma.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_impulse_noise_startle:{name:"Unexpected impulse noise startle limit",value:120,unit:"dB peak",kind:"threshold",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6 (Kryter 1994)",page:451,applicability:"spaceflight",quote:"unexpected impulse noise at the crewmember's ears should be limited to less than 120 dB peak sound pressure level",note:"Prevents startle.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_infrasonic_noise_limit:{name:"Infrasonic noise limit (1-20 Hz)",value:150,unit:"dB",kind:"design-limit",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6 (ACGIH 2001)",page:452,applicability:"spaceflight",quote:"Infrasonic sound pressure levels, including frequencies from 1 to 20 Hz, should be limited to less than 150 dB",note:"Prevents nausea/lightheadedness; hearing protection ineffective here.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_alarm_audibility_margin_66:{name:"Loudspeaker alarm audibility margin above masked threshold",value:13,unit:"dB",kind:"design-limit",group:"Environment — acoustics",source:"NASA/SP-2010-3407 (HIDH) §6.6 (ISO 7731:2003)",page:452,applicability:"spaceflight",quote:"alarms must produce nonspeech auditory annunciations that exceed the masked threshold by at least 13 dB in one or more one-third octave bands",note:"Ensures alarms are salient at work/sleep head locations.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_resonance_whole_body_sitting:{name:"Resonant frequency, whole body sitting vertical",value:5,unit:"Hz (5–6)",kind:"threshold",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7",page:475,applicability:"general",quote:"Whole body, sitting vertical | 5-6",note:"Body-component mechanical resonance at 1 G (Table 6.7-2).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_resonance_eyeball:{name:"Resonant frequency, eyeball",value:40,unit:"Hz (40–90)",kind:"threshold",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7",page:475,applicability:"general",quote:"Eyeball | 40-90",note:"Eyeball resonance; relevant to vibration-induced visual blur (Table 6.7-2).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_resonance_head_relative_body:{name:"Resonant frequency, head relative to body",value:20,unit:"Hz (20–30)",kind:"threshold",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7",page:475,applicability:"general",quote:"Head, relative to body | 20-30",note:"Head-on-body resonance at 1 G (Table 6.7-2).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_resonance_spinal_column:{name:"Resonant frequency, spinal column",value:8,unit:"Hz",kind:"threshold",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7",page:475,applicability:"general",quote:"Spinal column | 8",note:"Spinal-column resonance at 1 G (Table 6.7-2).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_vibration_perception_threshold:{name:"Whole-body vibration perception threshold (2-100 Hz)",value:.015,unit:"m/s^2 RMS",kind:"threshold",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7 (Griffin 1990; MIL-STD-1472G)",page:476,applicability:"general",quote:"The human perception threshold for 2- to 100-Hz vibration is approximately 0.015 m/s2 RMS at the most sensitive frequencies (1-10 Hz)",note:"25th-percentile Wk-weighted perceptual threshold, all axes.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_motion_sickness_sensitivity_band:{name:"Peak motion-sickness sensitivity frequency band",value:.1,unit:"Hz (0.1–0.3)",kind:"threshold",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7",page:476,applicability:"general",quote:"The greatest sensitivity to vibration acceleration occurs between approximately 0.1 and 0.3 Hz.",note:"Motion sickness caused by vertical oscillation at or below 0.5 Hz.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_vibration_health_risk_upper:{name:"Weighted vibration upper health-risk boundary (10-min)",value:.6,unit:"g RMS",kind:"design-limit",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7 (ISO 2631-1 1997)",page:483,applicability:"general",quote:"plotted values of 0.6 g (RMS weighted) for a 10-minute exposure",note:"Above this line health risks are likely; scales as aw^2*t.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_vibration_apollo_short_limit:{name:"Recommended short-duration vibration limit (1-25 min)",value:.4,unit:"g RMS",kind:"design-limit",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7 (Temple et al. 1964)",page:483,applicability:"spaceflight",quote:"intense vibration exposures, between 1 and 10 minutes in duration, should be reduced to 0.4 g",note:"Applied ~1 to 25 minutes (red line, Figure 6.7-5).",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_vor_failure_frequency:{name:"Frequency above which VOR gaze stabilization fails",value:8,unit:"Hz",kind:"threshold",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7",page:488,applicability:"general",quote:"Up until approximately 8 Hz, the vestibular sensory apparatus ... At vibration frequencies above these values, these reflex mechanisms begin to fail",note:"Above ~8 Hz retinal images oscillate and blur.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_dynamic_visual_acuity_detection:{name:"Vibrating-target detection threshold (dynamic visual acuity)",value:1,unit:"arcmin (±)",kind:"threshold",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7",page:488,applicability:"general",quote:"a detection threshold for a vibrating target of at least ±1 arcmin. Vibration amplitudes greater than ±2 arcmin will ... affect reading ability",note:"Amplitudes above ±2 arcmin degrade reading.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_gemini_crew_vibration_limit:{name:"Gemini crew vibration limit (11-Hz)",value:.25,unit:"g",kind:"design-limit",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7 (Vykukal & Dolkas 1966)",page:489,applicability:"spaceflight",quote:"specification of the Gemini crew vibration limit of 0.25 g",note:"Historical program vibration limit for 11-Hz Titan-II POGO; decrements began at 0.3 g.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_dial_reading_error_onset:{name:"Fine-scale dial-reading error onset, 11-Hz vibration",value:.4,unit:"g",kind:"error-rate",group:"Environment — vibration",source:"NASA/SP-2010-3407 (HIDH) §6.7 (Clarke et al. 1965; Vykukal & Dolkas 1966)",page:490,applicability:"general",quote:"error rates were significant for fine-scale dial-gauge reading beginning at 0.4 g (the lowest non-zero vibration level tested) for 11-Hz vibration",note:"Coarse-scale dials were generally resistant to reading errors.",section:"§6.5 Acceleration / §6.6 Acoustics / §6.7 Vibration"},hf_display_min_viewing_distance_nasa:{name:"Minimum display viewing distance (NASA-STD-3000)",value:33,unit:"cm (pref 51)",kind:"design-limit",group:"Interface — display viewing",source:"NASA/SP-2010-3407 (HIDH) §10.3 (NASA-STD-3000)",page:908,applicability:"spaceflight",quote:"NASA-STD-3000 suggested a minimum viewing distance of 33 cm, with a preference of 51 cm.",note:"Minimum direct-view display viewing distance.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_accommodation_min_viewing_distance:{name:"Accommodation-limited minimum viewing distance",value:40,unit:"cm",kind:"threshold",group:"Interface — display viewing",source:"NASA/SP-2010-3407 (HIDH) §10.3 (HFES 2007)",page:909,applicability:"general",quote:"Accommodation limits suggest a minimum viewing distance (for a direct-view display) of 40 cm",note:"Human accommodation sets a ~40 cm floor.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_gaze_angle_center:{name:"Preferred display-center gaze angle (HFES)",value:-17,unit:"deg",kind:"design-limit",group:"Interface — display viewing",source:"NASA/SP-2010-3407 (HIDH) §10.3 (HFES 2007)",page:910,applicability:"general",quote:"the display area lie within gaze angles of 0° to –60°, and that the display center be at about –17°.",note:"Display area within 0° to -60° gaze angle.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_indicator_contrast_min:{name:"Minimum indicator contrast (NASA 1995)",value:.5,unit:"Michelson contrast",kind:"threshold",group:"Interface — display contrast",source:"NASA/SP-2010-3407 (HIDH) §10.3 (NASA 1995)",page:921,applicability:"spaceflight",quote:"requires that indicators have a contrast of 0.5, except for displays viewed in sunlight.",note:"90% required in low ambient light.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_low_ambient_contrast:{name:"Required contrast in low ambient light (NASA 1995)",value:90,unit:"%",kind:"threshold",group:"Interface — display contrast",source:"NASA/SP-2010-3407 (HIDH) §10.3 (NASA 1995)",page:921,applicability:"spaceflight",quote:"In applications where ambient light is low, contrast should be 90%.",note:"Higher contrast required where ambient illumination is low.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_projected_contrast_ratio:{name:"Required projected-display contrast ratio (NASA 1995)",value:200,unit:"contrast ratio",kind:"threshold",group:"Interface — display contrast",source:"NASA/SP-2010-3407 (HIDH) §10.3 (NASA 1995)",page:921,applicability:"spaceflight",quote:'For projected displays, a contrast ratio (called "luminance ratio") of 200 is required',note:"Projected displays require luminance ratio of 200.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_alphanumeric_michelson_contrast:{name:"Alphanumeric VDT character Michelson contrast (NASA 1995)",value:.88,unit:"Michelson contrast (0.88–0.9)",kind:"threshold",group:"Interface — display contrast",source:"NASA/SP-2010-3407 (HIDH) §10.3 (NASA 1995)",page:921,applicability:"general",quote:"the Michelson contrast of characters is required to be between 0.88 and 0.9.",note:"Alphanumeric character contrast requirement.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_ambient_contrast_ratio_min:{name:"Minimum ambient contrast ratio (HFES)",value:3,unit:"contrast ratio",kind:"threshold",group:"Interface — display contrast",source:"NASA/SP-2010-3407 (HIDH) §10.3 (HFES 2007)",page:921,applicability:"general",quote:"it requires an ambient contrast ratio of at least 3 under all office illumination conditions.",note:"HFES minimum (default configuration 10).",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_visual_acuity_limit_cpd:{name:"Human spatial acuity limit",value:60,unit:"cycles/degree",kind:"threshold",group:"Interface — display resolution",source:"NASA/SP-2010-3407 (HIDH) §10.3",page:923,applicability:"general",quote:"human observers are unable to see spatial patterns above about 60 cycles per degree.",note:"Rendering it needs 120 pixels/degree.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_visual_resolution_max_ppd:{name:"Visual resolution to render acuity limit",value:120,unit:"pixels/degree",kind:"design-limit",group:"Interface — display resolution",source:"NASA/SP-2010-3407 (HIDH) §10.3 (Klein & Carney 1991)",page:923,applicability:"general",quote:"To render this frequency requires a visual resolution of 120 pixels per degree.",note:"Pixel density to reproduce the 60 cy/deg acuity limit.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_pixel_matrix_visible_ppd:{name:"Pixel-matrix visibility threshold",value:30,unit:"pixels/degree",kind:"threshold",group:"Interface — display resolution",source:"NASA/SP-2010-3407 (HIDH) §10.3",page:923,applicability:"general",quote:"At visual resolutions below about 30 pixels per degree, the pixel matrix itself may become visible",note:"Below ~30 ppd the discrete pixel structure becomes visible.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_flicker_fusion_limit:{name:"Luminance-modulation perception limit",value:60,unit:"Hz",kind:"threshold",group:"Interface — display temporal",source:"NASA/SP-2010-3407 (HIDH) §10.3",page:929,applicability:"general",quote:"human observers cannot see modulations of luminance more rapid than about 60 Hz.",note:"Basis for frame rates; flicker typically zero above ~70 Hz.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_response_time_hfes:{name:"Display on/off response time limit (HFES 2006)",value:55,unit:"ms",kind:"latency",group:"Interface — display temporal",source:"NASA/SP-2010-3407 (HIDH) §10.3 (HFES 2006)",page:933,applicability:"general",quote:"HFES2006 7.2.4.1 Response time On- and off-times < 55 ms",note:"HFES pixel on/off transition time budget.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_response_time_tco06:{name:"Display on/off response time limit (TCO-06)",value:13,unit:"ms",kind:"latency",group:"Interface — display temporal",source:"NASA/SP-2010-3407 (HIDH) §10.3 (TCO-06)",page:933,applicability:"general",quote:"TCO-06 A.2.8.2 Response time On- and off-times < 13 ms",note:"Stricter TCO-06 pixel response-time limit for moving imagery.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_char_acuity_min_arcmin:{name:"Minimum identifiable character height (20/20)",value:5,unit:"arcmin",kind:"threshold",group:"Interface — display text",source:"NASA/SP-2010-3407 (HIDH) §10.3",page:941,applicability:"general",quote:"subjects with normal visual acuity (20/20) cannot identify letters with a height less than 5 minutes of arc.",note:"Absolute acuity floor for letter identification.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_reading_char_width_optimal:{name:"Optimal character width for reading (Legge 1985)",value:24,unit:"arcmin (24–42)",kind:"design-limit",group:"Interface — display text",source:"NASA/SP-2010-3407 (HIDH) §10.3 (Legge 1985)",page:941,applicability:"general",quote:"The best reading rates were obtained for character widths between 24 min and 42 min",note:"Reasonable rates from 12 to 360 arcmin.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_reading_char_width_decline:{name:"Character width below which reading rate declines",value:12,unit:"arcmin",kind:"threshold",group:"Interface — display text",source:"NASA/SP-2010-3407 (HIDH) §10.3 (Legge et al. 1985)",page:941,applicability:"general",quote:"Rates declined rapidly for letters smaller than 12 min and for very large letters",note:"Reading rate falls off sharply below 12 arcmin.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_char_contrast_tco:{name:"Minimum character contrast (TCO'03/'06)",value:.7,unit:"Michelson contrast",kind:"threshold",group:"Interface — display text",source:"NASA/SP-2010-3407 (HIDH) §10.3 (TCO'03/TCO'06)",page:947,applicability:"general",quote:"TCO'03 and TCO'06 mandate that character contrast be greater than 0.7.",note:"TCO minimum displayable character contrast.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_display_viewing_angle_envelope_horizontal:{name:"Viewing-angle performance envelope, horizontal (HFES)",value:30,unit:"deg (±)",kind:"design-limit",group:"Interface — display viewing",source:"NASA/SP-2010-3407 (HIDH) §10.3 (HFES 2007)",page:939,applicability:"general",quote:"all of its requirements should be met within ± 30° horizontally, and +30° and –20° vertically.",note:"Angular envelope for meeting display specs.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_pushbutton_separation_min:{name:"Push-button minimum separation, single finger (MIL-STD-1472F)",value:13,unit:"mm (pref 50)",kind:"design-limit",group:"Interface — control spacing",source:"NASA/SP-2010-3407 (HIDH) §10.4 (MIL-STD-1472F)",page:970,applicability:"general",quote:'SEPARATION (S) Single Finger ... MIN 13 mm (0.5")',note:"Minimum edge-to-edge spacing between single-finger push buttons.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_key_repeat_rate:{name:"Key auto-repeat rate",value:10,unit:"characters/second",kind:"design-limit",group:"Interface — control dimension",source:"NASA/SP-2010-3407 (HIDH) §10.4",page:975,applicability:"general",quote:"If a key is held for longer than 500 milliseconds, the character should repeat at a rate of approximately 10 characters per second.",note:"Repeat begins after 500 ms hold.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_rocker_illumination_threshold:{name:"Rocker-switch internal-illumination luminance threshold",value:3.5,unit:"cd/m^2 (1 Ft-L)",kind:"threshold",group:"Interface — control coding",source:"NASA/SP-2010-3407 (HIDH) §10.4",page:980,applicability:"general",quote:"Rocker switches should be internally illuminated when ambient illumination will provide display luminance below 3.5 cd/m2 (1 Ft-L).",note:"Below this luminance rocker switches need internal illumination.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_joystick_response_delay_max:{name:"Joystick control-to-display response delay maximum",value:.1,unit:"s",kind:"latency",group:"Interface — control latency",source:"NASA/SP-2010-3407 (HIDH) §10.4 (MIL-STD-1472F)",page:989,applicability:"general",quote:"Delay between control movement and the confirming display response should be minimized and should be not greater than 0.1 second.",note:"Max acceptable control-display feedback latency for displacement joysticks.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_joystick_movement_max:{name:"Displacement joystick maximum excursion",value:45,unit:"deg",kind:"limit",group:"Interface — control dimension",source:"NASA/SP-2010-3407 (HIDH) §10.4 (MIL-STD-1472F)",page:989,applicability:"general",quote:"Movement should not exceed 45° from the center position and should be smooth in all directions.",note:"Maximum joystick deflection from center.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_isometric_joystick_max_force:{name:"Isometric joystick maximum full-output force",value:118,unit:"N (26.7 lb)",kind:"limit",group:"Interface — control force",source:"NASA/SP-2010-3407 (HIDH) §10.4",page:992,applicability:"general",quote:"Maximum force for full output should be not more than 118 N (26.7 lb).",note:"Upper force for full output of hand-operated isometric joystick.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_touchscreen_target_min:{name:"Touch-screen minimum target size",value:9.5,unit:"mm (max useful 22)",kind:"design-limit",group:"Interface — control dimension",source:"NASA/SP-2010-3407 (HIDH) §10.4 (MIL-STD-1472F/HFES)",page:996,applicability:"general",quote:"TARGET HEIGHT AND WIDTH (T) MIN 9.5 mm (0.4 in) MAX (ineffective beyond this size) 22 mm (0.9 in)",note:"Accuracy gains stop beyond 22 mm.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_touchscreen_deadspace_min:{name:"Touch-screen minimum dead space between targets",value:3.2,unit:"mm",kind:"design-limit",group:"Interface — control spacing",source:"NASA/SP-2010-3407 (HIDH) §10.4 (MIL-STD-1472F/HFES)",page:996,applicability:"general",quote:"DEAD SPACE BETWEEN TARGETS (D) MIN 3.2 mm (0.1 in)",note:"Minimum inter-target dead space to prevent accidental activation.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_rotary_positions_hidden_max:{name:"Rotary selector positions, not visible during operation",value:12,unit:"positions (24 if visible)",kind:"capacity",group:"Interface — control coding",source:"NASA/SP-2010-3407 (HIDH) §10.4",page:999,applicability:"general",quote:"A rotary selector switch that is not visible to the operator during normal system operation should have no more than 12 positions.",note:"Constantly-visible rotary switches may have up to 24 positions.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_color_coding_max_colors:{name:"Maximum colors for control coding",value:5,unit:"colors",kind:"capacity",group:"Interface — control coding",source:"NASA/SP-2010-3407 (HIDH) §10.4 (MIL-STD-1472F)",page:1017,applicability:"general",quote:"If color coding is required, not more than five colors should be used.",note:"Red, green, orange-yellow, white, optionally blue.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_shape_coding_max:{name:"Maximum shape-coded controls by absolute discrimination",value:10,unit:"shapes",kind:"capacity",group:"Interface — control coding",source:"NASA/SP-2010-3407 (HIDH) §10.4 (MIL-STD-1472F)",page:1017,applicability:"general",quote:"The number of shapes to be identified by each operator based on absolute discrimination should be not more than 10.",note:"Absolute-identification limit for shape-coded controls.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_highg_reach_reduction_3g:{name:"Forward-reach reduction at 3 g (Gx loading)",value:6,unit:"% (6%@3g,18%@4g,32%@5g)",kind:"degradation",group:"Interface — controls under g",source:"NASA/SP-2010-3407 (HIDH) §10.4 (Schafer & Bagian 1993)",page:1018,applicability:"spaceflight",quote:"a 6% reduction in forward reach displacement at 3 g, 18% at 4 g, and 32% at 5 g occurred",note:"Above 3 g limit control action to hand/wrist.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_steering_max_turns:{name:"Maximum steering-wheel turns lock to lock",value:3.5,unit:"turns",kind:"limit",group:"Interface — control dimension",source:"NASA/SP-2010-3407 (HIDH) §10.4 (MIL-STD-1472F)",page:1007,applicability:"aircraft",quote:"Maximum turning limits of vehicles should be achieved with not more than 3.5 turns of the steering wheel.",note:"Upper bound on steering-wheel revolutions.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_control_footswitch_resistance_min:{name:"Foot-switch minimum resistance (foot not resting)",value:18,unit:"N (4 lb)",kind:"design-limit",group:"Interface — control force",source:"NASA/SP-2010-3407 (HIDH) §10.4 (MIL-STD-1472F)",page:971,applicability:"general",quote:"RESISTANCE Foot Will Not Rest On Control Minimum 18 N (4 lb)",note:"Minimum pedal/foot-switch resistance.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_audio_tones_absolute_id_max:{name:"Maximum audio tones identifiable absolutely",value:4,unit:"tones",kind:"capacity",group:"Interface — audio displays",source:"NASA/SP-2010-3407 (HIDH) §10.7 (MIL-STD-1472F)",page:1037,applicability:"general",quote:"The number of audio tones to be identified absolutely should not exceed four.",note:"Humans can absolutely identify only ~5-6 tones; design limit four.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_audio_frequency_response_range:{name:"Optimal audio equipment frequency response",value:null,unit:"Hz (200–6100)",kind:"design-limit",group:"Interface — audio displays",source:"NASA/SP-2010-3407 (HIDH) §10.7",page:1038,applicability:"general",quote:"most essential to intelligibility (i.e., 200 to 6,100 Hz).",note:"Minimum acceptable range 250-4,000 Hz.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_audio_noise_canceling_threshold:{name:"Noise-canceling microphone requirement threshold",value:85,unit:"dBA",kind:"threshold",group:"Interface — audio displays",source:"NASA/SP-2010-3407 (HIDH) §10.7",page:1038,applicability:"general",quote:"Noise-canceling microphones and other input devices are required for high-noise environments (85 dBA or above)",note:"Ambient level at/above which noise-canceling input devices are required.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_audio_alarm_margin_above_masked_threshold:{name:"Nonspeech alarm margin above masked threshold",value:13,unit:"dB",kind:"threshold",group:"Interface — audio displays",source:"NASA/SP-2010-3407 (HIDH) §10.7 (ISO 7731:2003)",page:1039,applicability:"general",quote:"produce nonspeech auditory annunciations that exceed the masked threshold by at least 13 dB in one or more one-third octave bands",note:"Loudspeaker alarm salience margin per ISO 7731:2003.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_audio_reverberation_time_max:{name:"Maximum reverberation time in crew volume",value:.6,unit:"s",kind:"limit",group:"Interface — audio displays",source:"NASA/SP-2010-3407 (HIDH) §10.7 (Harris 1991)",page:1039,applicability:"spaceflight",quote:"a reverberation time in the crew habitable volume of less than 0.6 seconds within the 500 Hz, 1 kHz, and 2 kHz octave bands.",note:"Limits speech-intelligibility degradation.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_audio_headphone_drive_spl_min:{name:"Minimum communication-channel drive SPL",value:110,unit:"dB",kind:"design-limit",group:"Interface — audio displays",source:"NASA/SP-2010-3407 (HIDH) §10.7",page:1041,applicability:"general",quote:"enough electrical power to drive sound pressure level to at least 110 dB overall when using two earphones.",note:"Minimum SPL capability for volume/gain controls.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_class3_alert_tone:{name:"Shuttle Class 3 (caution) alert tone",value:550,unit:"Hz (±55)",kind:"design-limit",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9 (SFOC 2004)",page:1047,applicability:"spaceflight",quote:"Class 3 alert Continuous tone of 550 (± 55) Hz",note:"Class 3 caution continuous tone.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_class2_alternating_tone:{name:"Shuttle Class 2 (warning) alternating tone",value:null,unit:"Hz (400 & 1024 @ 2.5 Hz)",kind:"design-limit",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9 (SFOC 2004)",page:1047,applicability:"spaceflight",quote:"Class 2 tone Alternating signal of 400 and 1024 Hz at a 2.5-Hz rate",note:"Class 2 warning alternating two-tone signal.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_class1_siren_sweep:{name:"Shuttle Class 1 (emergency) siren frequency sweep",value:null,unit:"Hz (666→1470 over 5 s)",kind:"design-limit",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9 (SFOC 2004)",page:1047,applicability:"spaceflight",quote:"Class 1 siren Varying frequency from 666 Hz (± 66 Hz) to 1470 Hz (± 147 Hz) and return over 5 (±.5) seconds",note:"Smoke-detection emergency siren sweep.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_alert_tolerance:{name:"Class 1-3 alert frequency/timing tolerance",value:10,unit:"%",kind:"limit",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9 (SFOC 2004)",page:1047,applicability:"spaceflight",quote:"the tolerances for frequency and timing are 10% of the specified value.",note:"Allowed deviation on specified alert frequencies and timings.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_alarm_snr_target:{name:"Commonly cited alarm signal-to-noise target",value:15,unit:"dBA",kind:"threshold",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9",page:1048,applicability:"general",quote:"A signal-to-noise ratio of 15 dB(A) is a commonly cited target signal-to-noise ratio for alarms",note:"Overall A-weighted SNR target; ISO 7731 uses ≥13 dB per octave band.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_alarm_frequency_band:{name:"Auditory alarm frequency-component band",value:null,unit:"kHz (0.2–4)",kind:"design-limit",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9",page:1049,applicability:"general",quote:"frequency components in the region of relative maximal hearing sensitivity, 0.2 to 4 kHz",note:"Recommended alarm spectral region.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_abstract_alarm_limit:{name:"Learnable abstract-alarm set limit (Patterson 1982)",value:4,unit:"alarms",kind:"capacity",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9 (Patterson 1982)",page:1050,applicability:"general",quote:"Patterson (1982) set a limit of four alarms for easy acquisition",note:"Number of distinct abstract alarms crew can reliably acquire.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_precursor_level_reduction:{name:"Startle-mitigating precursor-alert level reduction",value:null,unit:"dB (-6 to -10)",kind:"design-limit",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9",page:1051,applicability:"general",quote:"The level of the alert is played –6 to –10 dB lower on its initial presentation than on successive presentations.",note:"Lowering the first presentation reduces startle.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_sound_level_max_orbit:{name:"Maximum auditory alarm sound level during orbit",value:85,unit:"dBA (115 launch/reentry)",kind:"limit",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9",page:1052,applicability:"spaceflight",quote:"Sound levels cannot exceed 85 dB(A) during orbit or 115 dB(A) during launch or reentry.",note:"Alarm ceiling by mission phase.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_color_coding_max:{name:"Maximum colors in caution & warning coding system",value:9,unit:"colors",kind:"capacity",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9 (SSP 50005)",page:1052,applicability:"spaceflight",quote:"No more than nine colors, including white and black, should be used in a coding system.",note:"Color-count ceiling for CWS indicator-light coding.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_indicator_brightness_ratio:{name:"Minimum caution/warning indicator brightness ratio",value:3,unit:"× other indicators",kind:"threshold",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9 (SSP 50005)",page:1053,applicability:"spaceflight",quote:"Indicator lights must be at least three times brighter than the other indicators on the same panel.",note:"Relative brightness requirement for C&W indicator lights.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"},hf_cw_flash_rate_range:{name:"Caution/warning flashing-light rate",value:null,unit:"flashes/s (3–5)",kind:"design-limit",group:"Interface — caution & warning",source:"NASA/SP-2010-3407 (HIDH) §10.9 (SSP 50005)",page:1053,applicability:"spaceflight",quote:"their flash rate must be within three to five flashes per second with on and off times of approximately equal duration.",note:"Must burn steadily if flasher fails.",section:"§10 Crew Interfaces (Displays, Controls, Audio, C&W)"}};typeof window<"u"&&(window.HF_REFERENCE_PRESETS=HF_REFERENCE_PRESETS),typeof module<"u"&&(module.exports=HF_REFERENCE_PRESETS);
